insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000001', 'problem-definition', 'صياغة المشكلة وسؤال القرار', 'كيف تحوّل شكوى عامة إلى سؤال قرار محدد قابل للتحليل، وتميّز بين العرض والسبب والحل.', 'beginner', 1, '{"learning_objective":"بنهاية الوحدة تستطيع إعادة صياغة أي طلب غامض من صاحب قرار إلى «سؤال قرار» واحد محدد، مع تحديد الهدف والقيود والجهة المعنية، والتمييز بين العرض والسبب والحل.","explanation":["أكثر أخطاء المستشارين المبتدئين تكلفة هو البدء بالتحليل قبل الاتفاق على المشكلة. عندما يقول نائب الأمين «المشاريع متأخرة» فهذا وصف لعرض (Symptom) وليس مشكلة قابلة للحل. المشكلة الحقيقية قد تكون نقص موارد المقاولين، أو بطء التصاريح، أو تغييرات النطاق. وكل سبب يقود إلى قرار مختلف.","سؤال القرار (Decision Question) هو السؤال الذي إذا أُجيب عنه اتخذ صاحب القرار فعلًا محددًا. يبدأ عادة بـ«هل» أو «أي» أو «كيف» ويحدد: الفاعل، الخيار، الهدف، القيد، والزمن. مثال: «هل توجه وكالة المشاريع 15% من اعتماد الصيانة إلى حدائق الأحياء خلال السنة القادمة لرفع الرضا إلى 70% دون زيادة الميزانية؟».","قبل الصياغة، اسأل خمسة أسئلة: من صاحب القرار؟ ما الفعل الذي سيتخذه؟ ما الهدف القابل للقياس؟ ما القيود غير القابلة للتفاوض؟ ما الأفق الزمني؟ الإجابات الخمس تشكل «ميثاق المشكلة» الذي يُتفق عليه في أول اجتماع.","التمييز الثلاثي: العرض ما يُلاحَظ (تأخر، شكاوى، تجاوز تكلفة)؛ السبب ما يولّد العرض (نقص معدات، غياب بوابة تغيير نطاق)؛ الحل ما يعالج السبب (خطة تعافٍ، بوابة اعتماد). الخطأ الشائع: صياغة المشكلة كحل مسبق («نحتاج نظامًا جديدًا») أو كعرض فقط («الرضا منخفض»)."],"terms":[{"ar":"سؤال القرار","en":"Decision Question","definition":"سؤال محدد تؤدي الإجابة عنه إلى فعل واضح من صاحب القرار."},{"ar":"العرض","en":"Symptom","definition":"الظاهرة الملاحظة التي تشير إلى وجود مشكلة دون تفسيرها."},{"ar":"السبب الجذري","en":"Root Cause","definition":"العامل الذي إذا عولج اختفى العرض ولم يعد."},{"ar":"ميثاق المشكلة","en":"Problem Charter","definition":"وثيقة قصيرة تحدد صاحب القرار والهدف والقيود والنطاق والزمن."},{"ar":"النطاق","en":"Scope","definition":"حدود ما يدخل في التحليل وما يُستبعد منه صراحة."}],"method_steps":["اسمع الطلب كما ورد ودوّنه حرفيًا دون تفسير.","حدد صاحب القرار الحقيقي (من يوقّع، لا من يطلب).","اسأل: ما الفعل الذي سيتغير إذا أجبنا؟ إن لم يوجد فعل فليس سؤال قرار.","حدد الهدف بمقياس ورقم وزمن (مثل: رفع الرضا من 58% إلى 70% خلال 12 شهرًا).","اذكر القيود الصلبة (ميزانية، عقود، أنظمة) والقيود القابلة للتفاوض.","صنّف ما لديك: أي العبارات عرض، وأيها سبب مفترض، وأيها حل مقترح.","اكتب سؤال القرار في جملة واحدة واعرضه على صاحب القرار للاتفاق."],"example_simple":{"title":"شكوى من تأخر الرد على البلاغات","situation":"مدير خدمات البلدية يقول: «الناس يشتكون من بطء الرد على بلاغات الإنارة».","application":"العرض: بطء الرد. الهدف المحتمل: خفض زمن الاستجابة من 9 أيام إلى 3. القيد: فريق الصيانة الحالي (6 فنيين). السؤال: «كيف تخفض إدارة الصيانة زمن الاستجابة لبلاغات الإنارة من 9 أيام إلى 3 خلال 6 أشهر بالفريق الحالي؟»","result":"تحوّل الطلب من شكوى إلى سؤال يقود إلى تحليل زمن كل خطوة في مسار البلاغ."},"example_medium":{"title":"طلب «نظام جديد لإدارة المشاريع»","situation":"وكيل الوكالة يطلب دراسة شراء نظام إدارة مشاريع جديد لأن 40% من المشاريع متعثرة.","application":"الطلب حل مسبق. أعد الصياغة: العرض تعثر 40%؛ الأسباب المحتملة: حوكمة، نطاق، موارد، أدوات. سؤال القرار: «ما التدخل الأعلى أثرًا لرفع المشاريع الملتزمة من 60% إلى 80% خلال 18 شهرًا ضمن الميزانية الحالية؟» والنظام أحد الخيارات لا الجواب.","result":"التحليل اللاحق أظهر أن 88% من التعثر حوكمي، فكان الحل بوابات وتصعيدًا لا نظامًا."},"example_advanced":{"title":"تعارض أهداف في محفظة طرق","situation":"نائب الأمين يريد «خفض الميزانية 22% دون المساس بالسلامة والوصول والالتزامات العلنية».","application":"ثلاثة أهداف وقيد مالي صلب: يجب ترتيب الأهداف. سؤال القرار: «أي المشاريع تُؤجَّل أو تُقلَّص لاستيعاب تخفيض 180 مليونًا مع تحقيق هدفي السلامة (15%) والوصول (85%)، وما الالتزامات العلنية التي يمكن إعادة جدولتها بأقل أثر؟»","result":"الصياغة كشفت أن الالتزام العلني قيد قابل للتفاوض بينما الهدفان الاستراتيجيان غير قابلين."},"common_mistakes":["صياغة المشكلة كحل مسبق («نحتاج تطبيقًا»).","ترك الهدف بلا رقم أو زمن.","الخلط بين صاحب الطلب وصاحب القرار.","إدراج أكثر من سؤال قرار في جملة واحدة.","تجاهل القيود الصلبة ثم اقتراح حل غير قابل للتنفيذ."],"checklist":["هل حددت صاحب القرار بالاسم أو المنصب؟","هل يؤدي الجواب إلى فعل واحد واضح؟","هل الهدف مقاس برقم وزمن؟","هل ذكرت القيود الصلبة صراحة؟","هل صنفت العبارات إلى عرض/سبب/حل؟","هل السؤال في جملة واحدة يمكن قراءتها في 10 ثوانٍ؟"],"exercise":{"prompt":"رئيس بلدية يقول: «الحدائق مهملة والناس غاضبون والميزانية زادت ولا أفهم أين تذهب». اكتب: (1) العرض، (2) سببين مفترضين، (3) سؤال قرار واحد بهدف رقمي وقيد صريح.","guidance":["ابدأ بالتمييز بين «مهملة» (حكم) و«الرضا 58%» (عرض مقاس).","الميزانية «زادت» قيد أم معلومة؟ اعتبرها قيدًا: لا زيادة إضافية.","اختر هدفًا واحدًا قابلًا للقياس ولا تجمع أهدافًا متعددة."]},"applied_case":{"title":"بلاغات الطرق في موسم الأمطار","scenario":"ارتفعت بلاغات تجمع المياه على الطرق من 320 إلى 780 بلاغًا في موسم واحد. تقول إدارة الطرق إن السبب الأمطار الاستثنائية، وتقول إدارة التشغيل إن المصارف لم تُنظَّف. طلب الأمين «حلًا سريعًا».","data":[{"label":"البلاغات (الموسم السابق / الحالي)","value":"320 / 780"},{"label":"كمية الأمطار (الموسم السابق / الحالي)","value":"48 ملم / 61 ملم"},{"label":"نسبة المصارف المنظفة قبل الموسم","value":"42% مقابل 88% في الموسم السابق"},{"label":"ميزانية تنظيف المصارف","value":"ثابتة"}],"task":"اكتب سؤال القرار الذي تعرضه على الأمين، مع التمييز بين العرض والسبب والحل، مستندًا إلى الأرقام.","model_answer":"العرض: ارتفاع البلاغات 144% (من 320 إلى 780). الأمطار زادت 27% فقط، فلا تفسر وحدها الارتفاع؛ بينما انخفضت نسبة المصارف المنظفة من 88% إلى 42%. السبب الأرجح: تراجع تنظيف المصارف قبل الموسم. سؤال القرار: «كيف ترفع إدارة التشغيل نسبة المصارف المنظفة قبل الموسم القادم من 42% إلى 90% بالميزانية الحالية، لتعود البلاغات إلى مستوى ≤ 350؟» الحل (خطة تنظيف مبكرة، مقاول إضافي، إعادة جدولة) يأتي بعد الاتفاق على السؤال."},"result_interpretation":[{"range":"85-100","meaning":"تميّز بين العرض والسبب وتصوغ سؤالًا قابلًا للفعل بالأرقام.","advice":"انتقل إلى وحدة MECE وشجرة القضايا."},{"range":"70-84","meaning":"الصياغة جيدة مع ضعف في تحديد القيود أو الرقم المستهدف.","advice":"أعد التمرين مع التركيز على القيود الصلبة."},{"range":"أقل من 70","meaning":"لا يزال الخلط بين العرض والحل قائمًا.","advice":"راجع الشرح وأمثلة الخطأ الشائع، ثم أعد الاختبار."}],"next_recommendation":"وحدة «MECE وشجرة القضايا» لتحويل سؤال القرار إلى هيكل تحليلي.","completion_rule":{"quiz_min_score":70,"applied_case_min_score":60,"description":"70% في الاختبار القصير و60% في الحالة التطبيقية."},"primary_skill":"problem_definition"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001101', '00000000-0000-4000-8000-000000000001', 'الدرس الأساسي: صياغة المشكلة وسؤال القرار', '{"explanation":["أكثر أخطاء المستشارين المبتدئين تكلفة هو البدء بالتحليل قبل الاتفاق على المشكلة. عندما يقول نائب الأمين «المشاريع متأخرة» فهذا وصف لعرض (Symptom) وليس مشكلة قابلة للحل. المشكلة الحقيقية قد تكون نقص موارد المقاولين، أو بطء التصاريح، أو تغييرات النطاق. وكل سبب يقود إلى قرار مختلف.","سؤال القرار (Decision Question) هو السؤال الذي إذا أُجيب عنه اتخذ صاحب القرار فعلًا محددًا. يبدأ عادة بـ«هل» أو «أي» أو «كيف» ويحدد: الفاعل، الخيار، الهدف، القيد، والزمن. مثال: «هل توجه وكالة المشاريع 15% من اعتماد الصيانة إلى حدائق الأحياء خلال السنة القادمة لرفع الرضا إلى 70% دون زيادة الميزانية؟».","قبل الصياغة، اسأل خمسة أسئلة: من صاحب القرار؟ ما الفعل الذي سيتخذه؟ ما الهدف القابل للقياس؟ ما القيود غير القابلة للتفاوض؟ ما الأفق الزمني؟ الإجابات الخمس تشكل «ميثاق المشكلة» الذي يُتفق عليه في أول اجتماع.","التمييز الثلاثي: العرض ما يُلاحَظ (تأخر، شكاوى، تجاوز تكلفة)؛ السبب ما يولّد العرض (نقص معدات، غياب بوابة تغيير نطاق)؛ الحل ما يعالج السبب (خطة تعافٍ، بوابة اعتماد). الخطأ الشائع: صياغة المشكلة كحل مسبق («نحتاج نظامًا جديدًا») أو كعرض فقط («الرضا منخفض»)."],"terms":[{"ar":"سؤال القرار","en":"Decision Question","definition":"سؤال محدد تؤدي الإجابة عنه إلى فعل واضح من صاحب القرار."},{"ar":"العرض","en":"Symptom","definition":"الظاهرة الملاحظة التي تشير إلى وجود مشكلة دون تفسيرها."},{"ar":"السبب الجذري","en":"Root Cause","definition":"العامل الذي إذا عولج اختفى العرض ولم يعد."},{"ar":"ميثاق المشكلة","en":"Problem Charter","definition":"وثيقة قصيرة تحدد صاحب القرار والهدف والقيود والنطاق والزمن."},{"ar":"النطاق","en":"Scope","definition":"حدود ما يدخل في التحليل وما يُستبعد منه صراحة."}],"method_steps":["اسمع الطلب كما ورد ودوّنه حرفيًا دون تفسير.","حدد صاحب القرار الحقيقي (من يوقّع، لا من يطلب).","اسأل: ما الفعل الذي سيتغير إذا أجبنا؟ إن لم يوجد فعل فليس سؤال قرار.","حدد الهدف بمقياس ورقم وزمن (مثل: رفع الرضا من 58% إلى 70% خلال 12 شهرًا).","اذكر القيود الصلبة (ميزانية، عقود، أنظمة) والقيود القابلة للتفاوض.","صنّف ما لديك: أي العبارات عرض، وأيها سبب مفترض، وأيها حل مقترح.","اكتب سؤال القرار في جملة واحدة واعرضه على صاحب القرار للاتفاق."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000010001', '00000000-0000-4000-8000-000000000001', 'problem_definition', 'beginner', 'mcq', 'أي العبارات التالية «سؤال قرار» صالح؟', '[{"id":"a","text":"لماذا الرضا عن الخدمات منخفض؟"},{"id":"b","text":"هل تعيد البلدية توجيه 10% من ميزانية الصيانة إلى حدائق الأحياء لرفع الرضا إلى 70% خلال عام دون زيادة الميزانية؟"},{"id":"c","text":"نحتاج إلى تطبيق جديد للبلاغات."},{"id":"d","text":"المشاريع متأخرة والمقاولون ضعفاء."}]'::jsonb, '{"option":"b"}'::jsonb, 'الخيار (ب) يحدد الفاعل والفعل والهدف الرقمي والقيد والزمن. (أ) سؤال تشخيصي، (ج) حل مسبق، (د) وصف عرض.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000010002', '00000000-0000-4000-8000-000000000001', 'problem_definition', 'beginner', 'matching', 'طابق كل عبارة بتصنيفها الصحيح.', '{"left":[{"id":"l1","text":"ارتفعت الشكاوى 40%"},{"id":"l2","text":"زمن الاستجابة طويل بسبب غياب مالك للبلاغ"},{"id":"l3","text":"تعيين مالك لكل بلاغ مع SLA 3 أيام"}],"right":[{"id":"r1","text":"عرض"},{"id":"r2","text":"سبب"},{"id":"r3","text":"حل"}]}'::jsonb, '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'الشكاوى ظاهرة ملاحظة (عرض)، غياب المالك يفسرها (سبب)، والتعيين يعالج السبب (حل).', true)
