insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000010003', '00000000-0000-4000-8000-000000000001', 'problem_definition', 'beginner', 'true_false', 'إذا طلب المدير «دراسة شراء نظام جديد» فالمهمة الأولى للمستشار هي مقارنة الأنظمة المتاحة.', '[]'::jsonb, '{"value":false}'::jsonb, 'الطلب حل مسبق؛ المهمة الأولى إعادة صياغة المشكلة وسؤال القرار، ثم يصبح النظام أحد الخيارات.', true)
