insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000010004', '00000000-0000-4000-8000-000000000001', 'problem_definition', 'beginner', 'ordering', 'رتب خطوات صياغة سؤال القرار.', '[{"id":"s1","text":"تحديد صاحب القرار"},{"id":"s2","text":"تدوين الطلب كما ورد"},{"id":"s3","text":"تحديد الهدف برقم وزمن"},{"id":"s4","text":"كتابة السؤال في جملة واحدة والاتفاق عليه"},{"id":"s5","text":"تحديد القيود الصلبة"}]'::jsonb, '{"order":["s2","s1","s3","s5","s4"]}'::jsonb, 'نبدأ بالطلب الخام، ثم صاحب القرار، ثم الهدف، ثم القيود، وأخيرًا الصياغة والاتفاق.', true)
