insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000010005', '00000000-0000-4000-8000-000000000001', 'problem_definition', 'beginner', 'spot_error', 'اقرأ التحليل: «ارتفعت بلاغات المياه 144% لأن الأمطار زادت 27%، لذلك نوصي بشراء مضخات إضافية». أين الخطأ؟', '[{"id":"a","text":"الأرقام غير صحيحة"},{"id":"b","text":"السبب المذكور لا يفسر حجم العرض، والتوصية حل مسبق دون تحليل الأسباب البديلة"},{"id":"c","text":"لا توجد توصية"},{"id":"d","text":"لا يوجد خطأ"}]'::jsonb, '{"option":"b"}'::jsonb, 'زيادة 27% في الأمطار لا تفسر ارتفاع 144% في البلاغات؛ يجب فحص أسباب أخرى (تنظيف المصارف) قبل القفز إلى حل.', true)
