insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000010006', '00000000-0000-4000-8000-000000000001', 'problem_definition', 'beginner', 'short_answer', 'أعد صياغة الطلب التالي إلى سؤال قرار: «الأمين يريد تقليل الازدحام قرب المدارس». (اذكر الفاعل، الفعل، الهدف الرقمي، القيد، الزمن)', '[]'::jsonb, '{"keywords":["هل","خلال","%","دون","الأمانة"],"min_matches":3}'::jsonb, 'إجابة نموذجية: «هل تطبق الأمانة نظام دخول متدرج لـ40 مدرسة لخفض زمن الازدحام الصباحي 30% خلال فصل دراسي دون إنشاءات جديدة؟»', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000002', 'mece-issue-tree', 'MECE وشجرة القضايا', 'تقسيم المشكلة إلى فروع لا تتداخل ولا تترك فجوة، وبناء أشجار القضايا والمنطق والمحركات.', 'beginner', 2, '{"learning_objective":"تبني شجرة قضايا MECE من سؤال القرار في أقل من 5 دقائق، وتميّز بين شجرة القضايا وشجرة المنطق وشجرة المحركات، وتحدد الفرع الذي يستحق التحليل أولًا.","explanation":["MECE (Mutually Exclusive, Collectively Exhaustive) قاعدة تقسيم: الفروع لا تتداخل (لا يقع عنصر في فرعين) وتغطي الكل (لا يبقى عنصر خارج الفروع). ليست هدفًا في ذاتها؛ الهدف أن تضمن أنك لم تُغفل سببًا ولم تعدّ سببًا مرتين.","شجرة القضايا (Issue Tree) تبدأ بسؤال القرار وتتفرع إلى أسئلة فرعية تجيب عنه. شجرة المنطق/الفرضيات تبدأ بجواب مقترح وتتفرع إلى ما يجب أن يكون صحيحًا ليصح الجواب. شجرة المحركات (Driver Tree) تفكك مقياسًا رقميًا إلى مكوناته الحسابية (الرضا المرجّح = مجموع رضا الفئة × وزنها).","أساليب التقسيم الشائعة: بالمعادلة (الإيراد = الحجم × السعر)، بالمراحل (قبل/أثناء/بعد التنفيذ)، بالأطراف (الجهة، المقاول، الجهات الخدمية)، بالفئات (كبرى/متوسطة/أحياء)، وبالأضداد (داخلي/خارجي). اختر الأسلوب الذي يجعل الفروع قابلة للقياس ببيانات متاحة.","الشجرة الجيدة ليست الأكثر فروعًا بل الأكثر توجيهًا: بعد بنائها تسأل «أي فرع يفسر معظم المشكلة؟» ثم تركز التحليل هناك (قاعدة 80/20). الفرع الذي لا يمكن اختباره ببيانات خلال الوقت المتاح فرع نظري."],"terms":[{"ar":"متنافية ومستنفدة","en":"MECE","definition":"تقسيم بلا تداخل بين الفروع وبلا فجوات في التغطية."},{"ar":"شجرة القضايا","en":"Issue Tree","definition":"تفكيك سؤال القرار إلى أسئلة فرعية."},{"ar":"شجرة الفرضيات","en":"Hypothesis / Logic Tree","definition":"تفكيك جواب مقترح إلى شروط يجب إثباتها."},{"ar":"شجرة المحركات","en":"Driver Tree","definition":"تفكيك مقياس رقمي إلى مكوناته الحسابية."},{"ar":"الفرع الحاسم","en":"Critical Branch","definition":"الفرع الذي يفسر الجزء الأكبر من المشكلة ويستحق التحليل أولًا."}],"method_steps":["ابدأ بسؤال القرار المتفق عليه في أعلى الشجرة.","اختر أسلوب التقسيم (معادلة، مراحل، أطراف، فئات).","اكتب 2-4 فروع في المستوى الأول واختبرها: هل يمكن أن يقع عنصر في فرعين؟ هل يوجد عنصر خارجها؟","فكك كل فرع مستوى واحدًا إضافيًا فقط في البداية.","اربط كل فرع ببيانات يمكن جمعها خلال الوقت المتاح.","قدّر وزن كل فرع تقديرًا أوليًا وحدد الفرع الحاسم.","اعرض الشجرة على صاحب القرار واطلب رأيه في الفرع الحاسم."],"example_simple":{"title":"تراجع زيارات حديقة","situation":"انخفضت زيارات حديقة كبرى 30% خلال عام.","application":"تقسيم بالأطراف والعوامل: (1) عوامل الحديقة نفسها (صيانة، مرافق، أمان)، (2) عوامل الوصول (مواقف، نقل، أعمال طرق)، (3) عوامل خارجية (بدائل جديدة، طقس، موسم). لا تداخل، وكل زائر متأثر بواحد منها على الأقل.","result":"البيانات أظهرت أن أعمال طريق أغلقت المدخل الرئيس 5 أشهر — الفرع الحاسم هو الوصول."},"example_medium":{"title":"تجاوز تكلفة مشروع جسر","situation":"تجاوز مشروع جسر التكلفة 18%.","application":"شجرة محركات: التجاوز = تغيير كميات + تغيير أسعار + أعمال إضافية غير مخططة + غرامات/مطالبات. ثم شجرة قضايا لكل محرك: لماذا زادت الكميات؟ (خطأ تصميم، ظروف موقع، طلبات الجهة).","result":"62% من التجاوز أعمال إضافية بسبب نقل خدمات غير محدد في التصميم — فرع واحد يفسر معظم المشكلة."},"example_advanced":{"title":"محفظة مشاريع متعثرة","situation":"40% من محفظة 85 مشروعًا متعثرة.","application":"تقسيم بمراحل دورة الحياة (بدء/تخطيط/تنفيذ/إغلاق) × أطراف (الجهة/المقاول/الجهات الخدمية). المصفوفة MECE وتسمح باكتشاف أن التعثر يتركز في «التنفيذ × الجهة» (تغييرات نطاق متأخرة) لا في «المقاول».","result":"التركيز على بوابة تغيير النطاق بدل معاقبة المقاولين."},"common_mistakes":["فروع متداخلة (مثل: «مالية» و«تكلفة المقاول»).","فرع «أخرى» كبير يخفي جهلًا بالمشكلة.","تفكيك مفرط في المستوى الثالث قبل التحقق من المستوى الأول.","شجرة عامة لا تخص الحالة (قالب محفوظ).","ذكر كلمة MECE في الإجابة دون هيكل فعلي."],"checklist":["هل يمكن أن يقع عنصر واحد في فرعين؟ (يجب: لا)","هل يوجد سبب معقول لا يندرج تحت أي فرع؟ (يجب: لا)","هل كل فرع قابل للقياس ببيانات متاحة؟","هل حددت الفرع الحاسم وبرّرته؟","هل الشجرة مخصصة لهذه الحالة لا قالبًا عامًا؟"],"exercise":{"prompt":"ابنِ شجرة قضايا من مستويين لسؤال: «لماذا ارتفع زمن استخراج رخص البناء من 12 يومًا إلى 31 يومًا؟» وحدد الفرع الذي تبدأ به مع سبب.","guidance":["جرّب التقسيم بمراحل المسار: تقديم → مراجعة فنية → اعتماد → إصدار.","اختبر التداخل: هل «نقص موظفين» فرع مستقل أم سبب داخل كل مرحلة؟","الفرع الحاسم عادة المرحلة التي تستهلك معظم الزمن الإضافي."]},"applied_case":{"title":"شجرة قضايا لارتفاع أوامر التغيير","scenario":"ارتفعت قيمة أوامر التغيير في محفظة الطرق من 4% إلى 13% من قيمة العقود خلال عامين. طلب مدير المحفظة هيكلة المشكلة قبل أي تدقيق.","data":[{"label":"قيمة أوامر التغيير (عامين)","value":"4% ← 13%"},{"label":"توزيع الأوامر بالمصدر","value":"طلبات الجهة 47%، ظروف موقع 28%، أخطاء تصميم 19%، أخرى 6%"},{"label":"نسبة المشاريع التي مرت بمراجعة تصميم مستقلة","value":"22%"},{"label":"متوسط زمن اعتماد أمر التغيير","value":"38 يومًا"}],"task":"ابنِ شجرة قضايا MECE بمستويين وحدد الفرع الحاسم بالأرقام.","model_answer":"الشجرة: أوامر التغيير ترتفع بسبب (1) مصدر الطلب: الجهة/الموقع/التصميم؛ (2) حوكمة الاعتماد: عتبة، زمن، مراجعة مستقلة؛ (3) التسعير: أسعار البنود الجديدة. الفرعان لا يتداخلان لأن المصدر «لماذا نشأ» والحوكمة «كيف اعتُمد». الفرع الحاسم: طلبات الجهة 47% + أخطاء تصميم 19% = 66% وكلاهما يرتبط بغياب مراجعة تصميم مستقلة (22% فقط من المشاريع). التوصية الأولية: بوابة مراجعة تصميم قبل الطرح وعتبة اعتماد لطلبات الجهة."},"result_interpretation":[{"range":"85-100","meaning":"تبني أشجارًا MECE مخصصة وتحدد الفرع الحاسم.","advice":"انتقل إلى التفكير القائم على الفرضيات."},{"range":"70-84","meaning":"الهيكل صحيح مع بعض التداخل أو فرع «أخرى» كبير.","advice":"أعد اختبار التداخل على شجرتك الأخيرة."},{"range":"أقل من 70","meaning":"الفروع قوائم أفكار لا هيكل.","advice":"راجع أساليب التقسيم وأعد التمرين بأسلوب المراحل."}],"next_recommendation":"وحدة «التفكير القائم على الفرضيات» لتحويل الفرع الحاسم إلى فرضية قابلة للاختبار.","completion_rule":{"quiz_min_score":70,"applied_case_min_score":60,"description":"70% في الاختبار و60% في الحالة التطبيقية."},"primary_skill":"structuring"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001102', '00000000-0000-4000-8000-000000000002', 'الدرس الأساسي: MECE وشجرة القضايا', '{"explanation":["MECE (Mutually Exclusive, Collectively Exhaustive) قاعدة تقسيم: الفروع لا تتداخل (لا يقع عنصر في فرعين) وتغطي الكل (لا يبقى عنصر خارج الفروع). ليست هدفًا في ذاتها؛ الهدف أن تضمن أنك لم تُغفل سببًا ولم تعدّ سببًا مرتين.","شجرة القضايا (Issue Tree) تبدأ بسؤال القرار وتتفرع إلى أسئلة فرعية تجيب عنه. شجرة المنطق/الفرضيات تبدأ بجواب مقترح وتتفرع إلى ما يجب أن يكون صحيحًا ليصح الجواب. شجرة المحركات (Driver Tree) تفكك مقياسًا رقميًا إلى مكوناته الحسابية (الرضا المرجّح = مجموع رضا الفئة × وزنها).","أساليب التقسيم الشائعة: بالمعادلة (الإيراد = الحجم × السعر)، بالمراحل (قبل/أثناء/بعد التنفيذ)، بالأطراف (الجهة، المقاول، الجهات الخدمية)، بالفئات (كبرى/متوسطة/أحياء)، وبالأضداد (داخلي/خارجي). اختر الأسلوب الذي يجعل الفروع قابلة للقياس ببيانات متاحة.","الشجرة الجيدة ليست الأكثر فروعًا بل الأكثر توجيهًا: بعد بنائها تسأل «أي فرع يفسر معظم المشكلة؟» ثم تركز التحليل هناك (قاعدة 80/20). الفرع الذي لا يمكن اختباره ببيانات خلال الوقت المتاح فرع نظري."],"terms":[{"ar":"متنافية ومستنفدة","en":"MECE","definition":"تقسيم بلا تداخل بين الفروع وبلا فجوات في التغطية."},{"ar":"شجرة القضايا","en":"Issue Tree","definition":"تفكيك سؤال القرار إلى أسئلة فرعية."},{"ar":"شجرة الفرضيات","en":"Hypothesis / Logic Tree","definition":"تفكيك جواب مقترح إلى شروط يجب إثباتها."},{"ar":"شجرة المحركات","en":"Driver Tree","definition":"تفكيك مقياس رقمي إلى مكوناته الحسابية."},{"ar":"الفرع الحاسم","en":"Critical Branch","definition":"الفرع الذي يفسر الجزء الأكبر من المشكلة ويستحق التحليل أولًا."}],"method_steps":["ابدأ بسؤال القرار المتفق عليه في أعلى الشجرة.","اختر أسلوب التقسيم (معادلة، مراحل، أطراف، فئات).","اكتب 2-4 فروع في المستوى الأول واختبرها: هل يمكن أن يقع عنصر في فرعين؟ هل يوجد عنصر خارجها؟","فكك كل فرع مستوى واحدًا إضافيًا فقط في البداية.","اربط كل فرع ببيانات يمكن جمعها خلال الوقت المتاح.","قدّر وزن كل فرع تقديرًا أوليًا وحدد الفرع الحاسم.","اعرض الشجرة على صاحب القرار واطلب رأيه في الفرع الحاسم."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000020001', '00000000-0000-4000-8000-000000000002', 'structuring', 'beginner', 'best_issue_tree', 'أي شجرة قضايا هي الأفضل لسؤال: «لماذا ارتفعت تكلفة صيانة الإنارة 25%؟»', '[{"id":"a","text":"(1) تكلفة العمالة (2) تكلفة المواد (3) تكلفة المقاول (4) أعمال طارئة"},{"id":"b","text":"(1) عدد الأعطال × (2) تكلفة الإصلاح للعطل الواحد"},{"id":"c","text":"(1) الصيف (2) الشتاء (3) مشاكل الشبكة"},{"id":"d","text":"(1) الإدارة (2) المقاول (3) المواد (4) الطقس (5) أخرى"}]'::jsonb, '{"option":"b"}'::jsonb, 'الخيار (ب) شجرة محركات MECE بمعادلة (حجم × تكلفة وحدة). (أ) تداخل بين «المقاول» و«العمالة/المواد»، (ج) و(د) فروع من طبقات مختلفة مع «أخرى».', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000020002', '00000000-0000-4000-8000-000000000002', 'structuring', 'beginner', 'mcq', 'ما المشكلة في التقسيم: «أسباب التأخر: (1) مالية (2) تعاقدية (3) تأخر دفعات المقاول»؟', '[{"id":"a","text":"لا يوجد فرع للطقس"},{"id":"b","text":"الفرع الثالث يتداخل مع الأول والثاني (ليس متنافيًا)"},{"id":"c","text":"الفروع كثيرة جدًا"},{"id":"d","text":"لا مشكلة"}]'::jsonb, '{"option":"b"}'::jsonb, 'تأخر الدفعات سبب مالي وتعاقدي في آن، فهو يقع داخل فرعين — انتهاك للتنافي.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000020003', '00000000-0000-4000-8000-000000000002', 'structuring', 'beginner', 'true_false', 'الشجرة التي تحتوي فروعًا أكثر تكون أفضل دائمًا لأنها أكثر شمولًا.', '[]'::jsonb, '{"value":false}'::jsonb, 'الشمول يتحقق بعدم وجود فجوات لا بكثرة الفروع؛ الفروع الزائدة تشتت التحليل وتؤخر تحديد الفرع الحاسم.', true)
