insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000020004', '00000000-0000-4000-8000-000000000002', 'structuring', 'beginner', 'matching', 'طابق نوع الشجرة بوصفها.', '{"left":[{"id":"l1","text":"شجرة القضايا"},{"id":"l2","text":"شجرة الفرضيات"},{"id":"l3","text":"شجرة المحركات"}],"right":[{"id":"r1","text":"تبدأ بسؤال وتتفرع إلى أسئلة"},{"id":"r2","text":"تبدأ بجواب مقترح وتتفرع إلى شروط إثباته"},{"id":"r3","text":"تفكك مقياسًا رقميًا إلى مكونات حسابية"}]}'::jsonb, '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'التمييز الثلاثي الأساسي بين أنواع الأشجار.', true)
