insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000020005', '00000000-0000-4000-8000-000000000002', 'structuring', 'beginner', 'most_important_data', 'لتحديد الفرع الحاسم في شجرة «ارتفاع أوامر التغيير»، أي بيانين هما الأهم أولًا؟ (اختر اثنين)', '[{"id":"a","text":"توزيع قيمة أوامر التغيير حسب المصدر"},{"id":"b","text":"أسماء المقاولين"},{"id":"c","text":"نسبة المشاريع التي مرت بمراجعة تصميم مستقلة"},{"id":"d","text":"عدد موظفي إدارة العقود"}]'::jsonb, '{"options":["a","c"]}'::jsonb, 'التوزيع بالمصدر يحدد الفرع الأثقل، ونسبة المراجعة المستقلة تختبر السبب الحوكمي خلفه.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000020006', '00000000-0000-4000-8000-000000000002', 'structuring', 'beginner', 'open_analysis', 'ابنِ شجرة قضايا بمستوى واحد (3-4 فروع) لسؤال: «لماذا ينخفض تحصيل رسوم المواقف 20%؟» واذكر أسلوب التقسيم الذي استخدمته.', '[]'::jsonb, '{"keywords":["عدد","سعر","تحصيل","تسرب","أسلوب"],"min_matches":3}'::jsonb, 'نموذج: التحصيل = عدد المستخدمين × متوسط الرسوم × نسبة التحصيل الفعلي (أسلوب المعادلة)؛ ثم لكل محرك أسباب.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000003', 'hypothesis-driven', 'التفكير القائم على الفرضيات', 'صياغة فرضية أولية قابلة للاختبار من اليوم الأول، وتحديد ما يثبتها أو ينفيها بأقل بيانات.', 'intermediate', 3, '{"learning_objective":"تصوغ فرضية محددة وقابلة للدحض لكل فرع حاسم، وتحدد اختبارًا واحدًا وبيانًا واحدًا يكفي لقبولها أو رفضها، وتراجع الفرضية عند ظهور دليل مخالف دون تعصب.","explanation":["التفكير القائم على الفرضيات يعكس ترتيب العمل: بدل جمع كل البيانات ثم الاستنتاج، تبدأ بجواب مؤقت مبني على الخبرة والبيانات الأولية، ثم تجمع فقط ما يلزم لاختباره. هذا يوفر 60-70% من وقت التحليل في المشاريع الاستشارية.","الفرضية الجيدة: محددة (تسمي السبب والأثر)، قابلة للدحض (يمكن أن تكون خاطئة)، ومرتبطة بقرار (إن صحّت تغير التوصية). «المشكلة في الحوكمة» ليست فرضية؛ «72% من تغييرات النطاق تصدر بعد التنفيذ لغياب بوابة اعتماد، وإدخال بوابة سيخفض التغييرات 50%» فرضية.","لكل فرضية اكتب «اختبار القتل»: ما البيان الذي إن ظهر أسقط الفرضية؟ إن لم تجد بيانًا يمكن أن يسقطها فهي ليست فرضية بل قناعة. ثم اطلب ذلك البيان أولًا — لا تبدأ بما يؤكد ما تعتقده (انحياز التأكيد).","في مقابلات الحالة، الفرضية المبكرة تجعل حوارك موجهًا: «فرضيتي أن نقص المعدات هو السبب، وللتحقق أطلب سجل المعدات الشهري». إن جاء السجل مخالفًا، تقول صراحة: «هذا ينفي فرضيتي، أنتقل إلى الفرضية التالية: التصاريح»."],"terms":[{"ar":"الفرضية الأولية","en":"Initial Hypothesis","definition":"جواب مؤقت لسؤال القرار يوجه جمع البيانات."},{"ar":"قابلية الدحض","en":"Falsifiability","definition":"إمكانية وجود دليل يُسقط الفرضية."},{"ar":"اختبار القتل","en":"Kill Test","definition":"البيان الواحد الذي إن ظهر أسقط الفرضية."},{"ar":"انحياز التأكيد","en":"Confirmation Bias","definition":"الميل إلى طلب ما يؤكد الاعتقاد وتجاهل ما ينفيه."},{"ar":"الفرضية البديلة","en":"Alternative Hypothesis","definition":"التفسير المنافس الذي يُختبر عند سقوط الفرضية الأولى."}],"method_steps":["من الفرع الحاسم في الشجرة، اكتب فرضية بصيغة: «السبب س يؤدي إلى الأثر ص بمقدار ن، وإن صح فالقرار ق».","اكتب فرضية بديلة واحدة على الأقل.","حدد اختبار القتل لكل فرضية.","رتب البيانات المطلوبة: الأسرع في الحسم أولًا.","اجمع البيان واحكم: قبول، رفض، أو تعديل الفرضية.","وثّق ما نُفي حتى لا يُعاد فتحه."],"example_simple":{"title":"بطء استخراج الرخص","situation":"زمن الرخصة ارتفع من 12 إلى 31 يومًا.","application":"الفرضية: مرحلة المراجعة الفنية تستهلك 15 يومًا إضافية بسبب إعادة الطلبات لنقص المستندات. اختبار القتل: إن كان زمن المراجعة الفنية لم يتغير فالفرضية خاطئة. البيان المطلوب: زمن كل مرحلة قبل وبعد.","result":"البيان أثبت أن المراجعة الفنية ارتفعت من 5 إلى 21 يومًا — فرضية مقبولة."},"example_medium":{"title":"تراجع الرضا رغم زيادة الإنفاق","situation":"الرضا انخفض 16 نقطة مع زيادة ميزانية 12%.","application":"الفرضية: الزيادة وُجهت إلى فئة حدائق راضية أصلًا (الكبرى) بينما تراجعت الأحياء. اختبار القتل: إن كانت الزيادة موزعة بالتساوي أو موجهة للأحياء فالفرضية خاطئة. البيان: توزيع الزيادة بالفئة.","result":"85% من الزيادة ذهبت لمهرجانات الكبرى — الفرضية صحيحة وقادت مباشرة إلى التوصية."},"example_advanced":{"title":"فرضيتان متنافستان في تعثر المحفظة","situation":"40% تعثر: الإدارة تلوم المقاولين، والمقاولون يلومون تغييرات النطاق.","application":"ف1: أداء المقاول هو المحرك (اختبار: توزيع التعثر بالمقاول متركز في قلة). ف2: تغيير النطاق المتأخر هو المحرك (اختبار: توقيت التغييرات نسبة إلى بدء التنفيذ). البيانات: التعثر موزع على 19 مقاولًا مختلفًا (ينفي ف1) و72% من التغييرات بعد التنفيذ (يثبت ف2).","result":"المستشار عرض الفرضيتين واختبارهما معًا فقبل الطرفان النتيجة."},"common_mistakes":["فرضية عامة لا يمكن دحضها («المشكلة معقدة ومتعددة الأسباب»).","طلب كل البيانات المتاحة بدل بيان الحسم.","التمسك بالفرضية بعد ظهور الدليل المخالف.","فرضية غير مرتبطة بقرار (تشخيص بلا أثر على التوصية).","عدم كتابة فرضية بديلة."],"checklist":["هل تسمي الفرضية سببًا وأثرًا ومقدارًا؟","هل يوجد بيان يمكن أن يُسقطها؟","هل طلبت بيان الحسم أولًا؟","هل لديك فرضية بديلة جاهزة؟","هل ذكرت صراحة ما نُفي؟"],"exercise":{"prompt":"الرضا عن خدمة البلاغات 52%. اكتب فرضيتين متنافستين، ولكل منهما اختبار قتل وبيانًا واحدًا تطلبه.","guidance":["فرّق بين «الاستجابة بطيئة» و«الإغلاق دون حل».","اختبار القتل يجب أن يكون رقمًا واحدًا واضحًا.","لا تطلب «كل بيانات النظام»."]},"applied_case":{"title":"ارتفاع تكلفة صيانة الإنارة","scenario":"ارتفعت تكلفة صيانة إنارة الطرق 25% خلال عام. المدير يرى أن السبب ارتفاع أسعار قطع الغيار.","data":[{"label":"إجمالي التكلفة (السابق / الحالي)","value":"8.0 / 10.0 مليون"},{"label":"عدد الأعطال","value":"6,400 / 8,900"},{"label":"متوسط تكلفة إصلاح العطل","value":"1,250 / 1,124 ريال"},{"label":"عمر الأعمدة","value":"38% من الأعمدة تجاوزت 15 سنة"}],"task":"اختبر فرضية المدير بالأرقام، واقترح الفرضية الأقوى مع اختبار قتل لها.","model_answer":"فرضية المدير (ارتفاع الأسعار) مرفوضة: متوسط تكلفة العطل انخفض 10% (من 1,250 إلى 1,124). المحرك هو عدد الأعطال (+39%). الفرضية الأقوى: تقادم 38% من الأعمدة يولد أعطالًا متكررة؛ اختبار القتل: إن كانت الأعطال موزعة بالتساوي بين الأعمدة القديمة والجديدة سقطت الفرضية. البيان المطلوب: توزيع الأعطال بعمر العمود. إن صحّت فالقرار: برنامج استبدال بدل زيادة ميزانية الصيانة."},"result_interpretation":[{"range":"85-100","meaning":"فرضياتك محددة وقابلة للدحض ومرتبطة بقرار.","advice":"انتقل إلى تحديد البيانات وجودتها."},{"range":"70-84","meaning":"الفرضيات جيدة لكن اختبار القتل غير واضح.","advice":"تدرب على كتابة بيان واحد يسقط كل فرضية."},{"range":"أقل من 70","meaning":"الفرضيات عامة أو قناعات.","advice":"راجع تعريف قابلية الدحض وأعد التمرين."}],"next_recommendation":"وحدة «تحديد البيانات والتحقق من جودتها».","completion_rule":{"quiz_min_score":70,"applied_case_min_score":60,"description":"70% في الاختبار و60% في الحالة التطبيقية."},"primary_skill":"hypotheses"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001103', '00000000-0000-4000-8000-000000000003', 'الدرس الأساسي: التفكير القائم على الفرضيات', '{"explanation":["التفكير القائم على الفرضيات يعكس ترتيب العمل: بدل جمع كل البيانات ثم الاستنتاج، تبدأ بجواب مؤقت مبني على الخبرة والبيانات الأولية، ثم تجمع فقط ما يلزم لاختباره. هذا يوفر 60-70% من وقت التحليل في المشاريع الاستشارية.","الفرضية الجيدة: محددة (تسمي السبب والأثر)، قابلة للدحض (يمكن أن تكون خاطئة)، ومرتبطة بقرار (إن صحّت تغير التوصية). «المشكلة في الحوكمة» ليست فرضية؛ «72% من تغييرات النطاق تصدر بعد التنفيذ لغياب بوابة اعتماد، وإدخال بوابة سيخفض التغييرات 50%» فرضية.","لكل فرضية اكتب «اختبار القتل»: ما البيان الذي إن ظهر أسقط الفرضية؟ إن لم تجد بيانًا يمكن أن يسقطها فهي ليست فرضية بل قناعة. ثم اطلب ذلك البيان أولًا — لا تبدأ بما يؤكد ما تعتقده (انحياز التأكيد).","في مقابلات الحالة، الفرضية المبكرة تجعل حوارك موجهًا: «فرضيتي أن نقص المعدات هو السبب، وللتحقق أطلب سجل المعدات الشهري». إن جاء السجل مخالفًا، تقول صراحة: «هذا ينفي فرضيتي، أنتقل إلى الفرضية التالية: التصاريح»."],"terms":[{"ar":"الفرضية الأولية","en":"Initial Hypothesis","definition":"جواب مؤقت لسؤال القرار يوجه جمع البيانات."},{"ar":"قابلية الدحض","en":"Falsifiability","definition":"إمكانية وجود دليل يُسقط الفرضية."},{"ar":"اختبار القتل","en":"Kill Test","definition":"البيان الواحد الذي إن ظهر أسقط الفرضية."},{"ar":"انحياز التأكيد","en":"Confirmation Bias","definition":"الميل إلى طلب ما يؤكد الاعتقاد وتجاهل ما ينفيه."},{"ar":"الفرضية البديلة","en":"Alternative Hypothesis","definition":"التفسير المنافس الذي يُختبر عند سقوط الفرضية الأولى."}],"method_steps":["من الفرع الحاسم في الشجرة، اكتب فرضية بصيغة: «السبب س يؤدي إلى الأثر ص بمقدار ن، وإن صح فالقرار ق».","اكتب فرضية بديلة واحدة على الأقل.","حدد اختبار القتل لكل فرضية.","رتب البيانات المطلوبة: الأسرع في الحسم أولًا.","اجمع البيان واحكم: قبول، رفض، أو تعديل الفرضية.","وثّق ما نُفي حتى لا يُعاد فتحه."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000030001', '00000000-0000-4000-8000-000000000003', 'hypotheses', 'intermediate', 'best_hypothesis', 'أي الفرضيات التالية الأقوى لتفسير ارتفاع زمن استخراج رخص البناء من 12 إلى 31 يومًا؟', '[{"id":"a","text":"الإجراءات معقدة والموظفون غير متعاونين."},{"id":"b","text":"مرحلة المراجعة الفنية ارتفعت من 5 إلى نحو 20 يومًا بسبب إعادة 60% من الطلبات لنقص مستندات، وإدخال قائمة تحقق مسبقة سيعيد الزمن إلى أقل من 15 يومًا."},{"id":"c","text":"النظام الإلكتروني بحاجة إلى تحديث."},{"id":"d","text":"المشكلة متعددة الأسباب وتحتاج دراسة شاملة."}]'::jsonb, '{"option":"b"}'::jsonb, 'الخيار (ب) يسمي السبب والأثر والمقدار والقرار، وقابل للدحض ببيان زمن المراحل.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000030002', '00000000-0000-4000-8000-000000000003', 'hypotheses', 'intermediate', 'true_false', 'الفرضية الجيدة هي التي يصعب إثبات خطئها.', '[]'::jsonb, '{"value":false}'::jsonb, 'العكس: الفرضية الجيدة قابلة للدحض؛ ما لا يمكن إسقاطه قناعة لا فرضية.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000030003', '00000000-0000-4000-8000-000000000003', 'hypotheses', 'intermediate', 'most_important_data', 'فرضيتك: «تقادم الأعمدة يولد الأعطال». أي بيانين تطلبهما أولًا للحسم؟ (اختر اثنين)', '[{"id":"a","text":"توزيع الأعطال بعمر العمود"},{"id":"b","text":"أسماء الفنيين"},{"id":"c","text":"معدل تكرار العطل للعمود الواحد بالعمر"},{"id":"d","text":"أسعار المصابيح في السوق"}]'::jsonb, '{"options":["a","c"]}'::jsonb, 'كلاهما يختبر العلاقة بين العمر والأعطال مباشرة؛ الأسعار تخص فرضية أخرى.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000030004', '00000000-0000-4000-8000-000000000003', 'hypotheses', 'intermediate', 'numeric', 'تكلفة الصيانة ارتفعت من 8.0 إلى 10.0 مليون، وعدد الأعطال من 6,400 إلى 8,900. ما نسبة ارتفاع عدد الأعطال (%) مقربة لأقرب عدد صحيح؟', '[]'::jsonb, '{"value":39,"tolerance":1}'::jsonb, '(8,900 − 6,400) ÷ 6,400 = 39%. ارتفاع التكلفة 25% أقل من ارتفاع الأعطال، أي أن تكلفة العطل الواحد انخفضت.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000030005', '00000000-0000-4000-8000-000000000003', 'hypotheses', 'intermediate', 'spot_error', '«فرضيتي أن المقاول ضعيف. طلبت تقارير المشرف عن أخطاء المقاول ووجدت 14 مخالفة، إذن الفرضية صحيحة.» ما الخطأ؟', '[{"id":"a","text":"لا خطأ؛ 14 مخالفة دليل كافٍ"},{"id":"b","text":"طلب دليلًا مؤكدًا فقط (انحياز تأكيد) دون اختبار قتل أو فرضية بديلة أو مقارنة بمقاولين آخرين"},{"id":"c","text":"كان يجب طلب المزيد من التقارير"},{"id":"d","text":"الفرضية يجب أن تكون عن التصميم"}]'::jsonb, '{"option":"b"}'::jsonb, '14 مخالفة بلا مرجع مقارنة (متوسط المخالفات في المشاريع المماثلة) ولا فرضية بديلة = انحياز تأكيد.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000030006', '00000000-0000-4000-8000-000000000003', 'hypotheses', 'intermediate', 'short_answer', 'اكتب فرضية واحدة قابلة للدحض عن سبب انخفاض تحصيل رسوم المواقف 20%، مع اختبار قتل لها.', '[]'::jsonb, '{"keywords":["فرضية","اختبار","إن","نسبة","بسبب"],"min_matches":3}'::jsonb, 'نموذج: «الانخفاض ناتج عن تعطل 30% من أجهزة الدفع؛ اختبار القتل: إن كان التحصيل انخفض بالنسبة نفسها في المواقف ذات الأجهزة السليمة فالفرضية خاطئة».', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000004', 'data-quality', 'تحديد البيانات والتحقق من جودتها', 'اختيار أقل البيانات الكافية للحسم، وفحص مصدرها وتعريفها وحداثتها قبل الاعتماد عليها.', 'intermediate', 4, '{"learning_objective":"تحدد لكل فرضية البيان الحاسم ومصدره ووحدته وتعريفه، وتكتشف مشكلات الجودة الشائعة (تعريفات مختلفة، فترات غير متطابقة، عينات منحازة) قبل بناء استنتاج عليها.","explanation":["المستشار لا يطلب «كل البيانات» بل «البيان الذي يحسم». لكل فرضية ثلاثة أسئلة: ما المقياس؟ ما المصدر؟ ما الفترة؟ ثم يضاف الرابع: ما التعريف؟ فـ«المشروع المتعثر» قد يعني في إدارة تأخر 10% وفي أخرى 20%.","أخطاء الجودة الشائعة في القطاع الحكومي: مقارنة فترات غير متطابقة (موسم أمطار مقابل عام كامل)، خلط القيم الاسمية بالحقيقية، عينات منحازة (استبيان رضا يُجاب عنه من الغاضبين فقط)، بيانات إدخال يدوي بلا تحقق، ومؤشرات بلا مالك لم تُحدَّث منذ أشهر.","مثلث التحقق: حين تشك في رقم، قارن ثلاثة مصادر مستقلة (النظام، التقرير المالي، الملاحظة الميدانية). إن اتفق اثنان وخالف الثالث، فالخلاف نفسه معلومة (غالبًا تعريف مختلف).","قاعدة «الكفاية»: توقف عن جمع البيانات عندما تكون الإجابة ثابتة تحت افتراضات معقولة. إن كان الفرق بين أفضل وأسوأ تقدير لا يغير القرار، فلا تحتاج دقة أعلى. هذه القاعدة تحمي من شلل التحليل."],"terms":[{"ar":"البيان الحاسم","en":"Decisive Data Point","definition":"أقل بيان يكفي لقبول الفرضية أو رفضها."},{"ar":"التعريف التشغيلي","en":"Operational Definition","definition":"الطريقة الدقيقة لحساب المقياس (مثل: التعثر = تأخر > 20% أو تجاوز > 10%)."},{"ar":"مثلث التحقق","en":"Triangulation","definition":"مقارنة الرقم من ثلاثة مصادر مستقلة."},{"ar":"انحياز العينة","en":"Sample Bias","definition":"عينة لا تمثل المجتمع المستهدف."},{"ar":"كفاية البيانات","en":"Data Sufficiency","definition":"الحد الذي بعده لا تغير دقة أعلى القرار."}],"method_steps":["لكل فرضية، اكتب البيان الحاسم بمقياس ووحدة وفترة.","حدد المصدر الأرجح ومالكه ووقت الحصول عليه.","اطلب التعريف التشغيلي للمقياس واكتبه.","افحص الفترة: هل تُقارن مثلًا بمثل؟","افحص التمثيل: هل العينة تشمل كل الفئات المعنية؟","ثلّث الأرقام الحرجة من مصدر ثانٍ.","اختبر الكفاية: هل تغيّر القرار عند ±20%؟"],"example_simple":{"title":"رضا السكان 58%","situation":"استبيان إلكتروني أُجاب عنه 410 من سكان الحي.","application":"اسأل: من أجاب؟ (رابط نُشر في مجموعة شكاوى — انحياز). ما الفترة؟ (أسبوع بعد موسم الأمطار). ما التعريف؟ (راضٍ = 4 أو 5 من 5).","result":"أُعيد المسح بعينة ممثلة فكان الرضا 66% — الفجوة أصغر مما ظُن، والقرار تغيّر من «حملة طوارئ» إلى «تحسين مستهدف»."},"example_medium":{"title":"نسبة التعثر 40%","situation":"تقرير PMO يقول 34 من 85 مشروعًا متعثر، وتقرير الإدارة المالية يقول 21.","application":"الفرق تعريف: PMO يعتبر التأخر > 20% تعثرًا، والمالية تعتبر تجاوز التكلفة فقط. ثلّث بالملاحظة: 29 مشروعًا تنطبق عليها القاعدتان أو إحداهما.","result":"اعتُمد تعريف موحد ومكتوب قبل أي تحليل، وحُدد مالك للمؤشر."},"example_advanced":{"title":"منافع مشروع تطوير حضري","situation":"تقدير المنافع 310 ملايين بُني على دراسة طلب عمرها 3 سنوات قبل تغيير مسار الطريق.","application":"البيان الحاسم: الزيارات المتوقعة بعد تغيير الطريق. المصدر: عدّاد مرور حالي + مقارنة مع مواقع مماثلة. اختبار الكفاية: عند −25% يبقى خيار النطاق المقلّص متفوقًا، فلا حاجة لدراسة كاملة قبل القرار المبدئي، بل بوابة تحقق لاحقة.","result":"قرار مبدئي خلال أسبوعين مع بوابة تحديث بدل انتظار دراسة 4 أشهر."},"common_mistakes":["طلب قوائم بيانات طويلة دون ربط بفرضية.","مقارنة فترات أو تعريفات غير متطابقة.","الثقة بالرقم لأنه صادر من نظام.","تجاهل حجم العينة وطريقة اختيارها.","الاستمرار في جمع البيانات بعد أن استقر القرار."],"checklist":["لكل بيان: مقياس، وحدة، فترة، مصدر، تعريف؟","هل الفترات متطابقة في المقارنة؟","هل العينة ممثلة؟","هل ثلّثت الأرقام الحرجة؟","هل اختبرت الكفاية عند ±20%؟"],"exercise":{"prompt":"فرضيتك: «تأخر نقل الخدمات يسبب 60% من تأخر مشاريع الطرق». حدد ثلاثة بيانات فقط تطلبها، ولكل منها: المقياس، المصدر، الفترة، التعريف، وسؤال جودة واحد.","guidance":["ابدأ بالبيان الذي يمكن أن يسقط الفرضية.","احذر من تعريف «تأخر نقل الخدمات» — من يسجله ومتى يبدأ العد؟","اطلب فترة تشمل مشاريع مكتملة لا الجارية فقط."]},"applied_case":{"title":"مؤشر زمن الاستجابة للبلاغات","scenario":"تقرير الأداء يقول إن متوسط زمن الاستجابة للبلاغات 2.1 يوم، بينما يشكو السكان من انتظار أسابيع. طُلب منك التحقق قبل عرض المؤشر على نائب الأمين.","data":[{"label":"متوسط زمن الاستجابة (النظام)","value":"2.1 يوم"},{"label":"تعريف «الاستجابة» في النظام","value":"تغيير حالة البلاغ إلى «قيد المعالجة»"},{"label":"متوسط زمن الإغلاق الفعلي","value":"11.4 يوم"},{"label":"نسبة البلاغات المغلقة بحالة «تم» دون زيارة ميدانية","value":"27%"},{"label":"توزيع البلاغات","value":"62% من 3 أحياء فقط"}],"task":"قيّم جودة المؤشر واقترح التعريف والبيانات التي يجب عرضها بدلًا منه.","model_answer":"المؤشر مضلل: «الاستجابة» تعني تغيير حالة لا معالجة، فالرقم 2.1 يوم يقيس نشاطًا إداريًا. الزمن الحقيقي للمواطن هو الإغلاق 11.4 يوم، و27% من الإغلاقات بلا زيارة ميدانية تشكك حتى في هذا الرقم. التوصية: تعريف تشغيلي جديد «زمن الحل = من التسجيل إلى تأكيد المواطن أو التحقق الميداني»، مع عرض المتوسط والوسيط ونسبة البلاغات المحلولة خلال 5 أيام، وتقسيم بالحي لأن 62% تتركز في 3 أحياء. مالك المؤشر: مدير التشغيل. تحقق شهري بعينة ميدانية 5%."},"result_interpretation":[{"range":"85-100","meaning":"تطلب البيان الحاسم وتكتشف مشكلات الجودة قبل الاستنتاج.","advice":"انتقل إلى التحليل الكمي."},{"range":"70-84","meaning":"تحدد البيانات جيدًا لكن تغفل التعريفات أو الفترات.","advice":"طبّق قائمة التحقق على أي رقم قبل استخدامه."},{"range":"أقل من 70","meaning":"تطلب قوائم بيانات عامة.","advice":"أعد التمرين مع تحديد بيان واحد لكل فرضية."}],"next_recommendation":"وحدة «التحليل الكمي والحساب الذهني».","completion_rule":{"quiz_min_score":70,"applied_case_min_score":60,"description":"70% في الاختبار و60% في الحالة التطبيقية."},"primary_skill":"data_identification"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001104', '00000000-0000-4000-8000-000000000004', 'الدرس الأساسي: تحديد البيانات والتحقق من جودتها', '{"explanation":["المستشار لا يطلب «كل البيانات» بل «البيان الذي يحسم». لكل فرضية ثلاثة أسئلة: ما المقياس؟ ما المصدر؟ ما الفترة؟ ثم يضاف الرابع: ما التعريف؟ فـ«المشروع المتعثر» قد يعني في إدارة تأخر 10% وفي أخرى 20%.","أخطاء الجودة الشائعة في القطاع الحكومي: مقارنة فترات غير متطابقة (موسم أمطار مقابل عام كامل)، خلط القيم الاسمية بالحقيقية، عينات منحازة (استبيان رضا يُجاب عنه من الغاضبين فقط)، بيانات إدخال يدوي بلا تحقق، ومؤشرات بلا مالك لم تُحدَّث منذ أشهر.","مثلث التحقق: حين تشك في رقم، قارن ثلاثة مصادر مستقلة (النظام، التقرير المالي، الملاحظة الميدانية). إن اتفق اثنان وخالف الثالث، فالخلاف نفسه معلومة (غالبًا تعريف مختلف).","قاعدة «الكفاية»: توقف عن جمع البيانات عندما تكون الإجابة ثابتة تحت افتراضات معقولة. إن كان الفرق بين أفضل وأسوأ تقدير لا يغير القرار، فلا تحتاج دقة أعلى. هذه القاعدة تحمي من شلل التحليل."],"terms":[{"ar":"البيان الحاسم","en":"Decisive Data Point","definition":"أقل بيان يكفي لقبول الفرضية أو رفضها."},{"ar":"التعريف التشغيلي","en":"Operational Definition","definition":"الطريقة الدقيقة لحساب المقياس (مثل: التعثر = تأخر > 20% أو تجاوز > 10%)."},{"ar":"مثلث التحقق","en":"Triangulation","definition":"مقارنة الرقم من ثلاثة مصادر مستقلة."},{"ar":"انحياز العينة","en":"Sample Bias","definition":"عينة لا تمثل المجتمع المستهدف."},{"ar":"كفاية البيانات","en":"Data Sufficiency","definition":"الحد الذي بعده لا تغير دقة أعلى القرار."}],"method_steps":["لكل فرضية، اكتب البيان الحاسم بمقياس ووحدة وفترة.","حدد المصدر الأرجح ومالكه ووقت الحصول عليه.","اطلب التعريف التشغيلي للمقياس واكتبه.","افحص الفترة: هل تُقارن مثلًا بمثل؟","افحص التمثيل: هل العينة تشمل كل الفئات المعنية؟","ثلّث الأرقام الحرجة من مصدر ثانٍ.","اختبر الكفاية: هل تغيّر القرار عند ±20%؟"]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000040001', '00000000-0000-4000-8000-000000000004', 'data_identification', 'intermediate', 'most_important_data', 'فرضية: «تراجع الرضا سببه بطء الاستجابة في حدائق الأحياء». اختر البيانين الأكثر أهمية للحسم.', '[{"id":"a","text":"زمن الاستجابة لبلاغات الصيانة حسب فئة الحديقة"},{"id":"b","text":"عدد الأشجار في كل حديقة"},{"id":"c","text":"الرضا حسب فئة الحديقة"},{"id":"d","text":"ميزانية المهرجانات الإجمالية"}]'::jsonb, '{"options":["a","c"]}'::jsonb, 'ربط زمن الاستجابة بالرضا لكل فئة يختبر الفرضية مباشرة.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000040002', '00000000-0000-4000-8000-000000000004', 'data_identification', 'intermediate', 'table_reading', 'من الجدول: أي إدارة لديها أعلى نسبة بلاغات مغلقة بلا زيارة ميدانية؟', '{"table":{"columns":["الإدارة","البلاغات","مغلقة بلا زيارة"],"rows":[["الطرق",1200,96],["الإنارة",800,216],["النظافة",2100,315],["الحدائق",600,120]]},"choices":[{"id":"a","text":"الطرق"},{"id":"b","text":"الإنارة"},{"id":"c","text":"النظافة"},{"id":"d","text":"الحدائق"}]}'::jsonb, '{"option":"b"}'::jsonb, 'الإنارة 216 ÷ 800 = 27%؛ النظافة 15%؛ الحدائق 20%؛ الطرق 8%. العدد المطلق (النظافة) يضلل.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000040003', '00000000-0000-4000-8000-000000000004', 'data_identification', 'intermediate', 'true_false', 'إذا كان الرقم صادرًا من النظام الإلكتروني الرسمي فلا حاجة للتحقق من تعريفه.', '[]'::jsonb, '{"value":false}'::jsonb, 'النظام يسجل ما عُرِّف له؛ مؤشر «الاستجابة» قد يقيس تغيير حالة لا معالجة فعلية.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000040004', '00000000-0000-4000-8000-000000000004', 'data_identification', 'intermediate', 'spot_error', '«انخفضت البلاغات 35% بعد الحملة: من 900 بلاغ في فبراير (موسم الأمطار) إلى 585 في يونيو». ما الخطأ؟', '[{"id":"a","text":"الحساب خاطئ"},{"id":"b","text":"مقارنة فترتين غير متطابقتين موسميًا (موسم أمطار مقابل صيف)"},{"id":"c","text":"الحملة لم تُذكر"},{"id":"d","text":"لا خطأ"}]'::jsonb, '{"option":"b"}'::jsonb, 'الانخفاض قد يكون موسميًا بالكامل؛ المقارنة الصحيحة مع يونيو السابق أو بعد تعديل الموسمية.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000040005', '00000000-0000-4000-8000-000000000004', 'data_identification', 'intermediate', 'numeric', 'استبيان رضا: 410 إجابات، 58% راضون. إن كانت العينة منحازة بحيث أُجيب عنها من سكان 3 أحياء تمثل 30% من السكان، فما الحد الأدنى لعدد الإجابات المطلوبة من بقية الأحياء ليصبح التمثيل متناسبًا (70% من الإجمالي) دون حذف الإجابات الحالية؟ (قرّب لأقرب عدد صحيح)', '[]'::jsonb, '{"value":957,"tolerance":3}'::jsonb, 'لتكون 410 = 30% من الإجمالي، الإجمالي = 1,367 والمطلوب من البقية 957.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000040006', '00000000-0000-4000-8000-000000000004', 'data_identification', 'intermediate', 'short_answer', 'اكتب التعريف التشغيلي المقترح لمؤشر «المشروع المتعثر» بحيث يمكن حسابه آليًا من بيانات المشاريع.', '[]'::jsonb, '{"keywords":["تأخر","تجاوز","%","أو"],"min_matches":3}'::jsonb, 'نموذج: «المشروع متعثر إذا كان الانحراف الزمني > 20% من المدة المخططة أو تجاوز التكلفة > 10% من العقد، يُحسب شهريًا من نظام إدارة المشاريع».', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000005', 'quantitative-mental-math', 'التحليل الكمي والحساب الذهني', 'الحسابات الاستشارية الأساسية بسرعة ودقة: النسب، النمو، التوزيع، الاستدلال العكسي، وتحليل الحساسية.', 'beginner', 5, '{"learning_objective":"تنفذ الحسابات الشائعة في الحالات (نسبة، تغير، مرجّح، لكل وحدة، تعادل، حساسية) ذهنيًا أو على ورقة خلال 30-60 ثانية، وتفسر معنى الرقم للقرار لا الرقم فقط.","explanation":["في مقابلات الحالة يُقاس ليس فقط صحة الرقم بل طريقة الوصول إليه بصوت مسموع: «الاعتماد 820، التخفيض 22%، أي نحو خُمس إلا قليلًا: 820 × 0.2 = 164، زائد 820 × 0.02 = 16.4، المجموع 180.4». التفكيك إلى أجزاء سهلة (10%، 1%، 5%) هو المهارة الأساسية.","الحسابات الخمسة الأكثر تكرارًا: (1) النسبة والتغير النسبي، (2) المتوسط المرجّح، (3) القيمة لكل وحدة (لكل مليون، لكل زيارة، لكل كم)، (4) نقطة التعادل والاستدلال العكسي (كم يلزم لبلوغ الهدف؟)، (5) الحساسية (ماذا لو تغير المدخل ±25%؟).","التقريب الذكي: قرّب إلى رقم قريب سهل ثم صحح. 4.6 ÷ 9.6 ≈ 4.6 ÷ 10 = 46% ثم أضف 4% تقريبًا (لأن المقام أصغر) = 48%. القيمة الدقيقة 47.9%. الدقة المطلوبة عادة ±2% للتوصية، وصرّح بالتقريب.","أخطاء قاتلة: خلط النقاط المئوية بالنسب المئوية (من 58% إلى 70% = 12 نقطة، أي +21%)، الجمع بين قيم بوحدات مختلفة، حساب الحساسية على متغير واحد وتجاهل الآخر، ونسيان التكلفة الغارقة (أو إدخالها حين يجب استبعادها)."],"terms":[{"ar":"نقطة مئوية","en":"Percentage Point","definition":"الفرق المطلق بين نسبتين (70% − 58% = 12 نقطة)."},{"ar":"متوسط مرجّح","en":"Weighted Average","definition":"مجموع القيم × أوزانها ÷ مجموع الأوزان."},{"ar":"الاستدلال العكسي","en":"Back-solving","definition":"حساب المدخل المطلوب لبلوغ هدف محدد."},{"ar":"تحليل الحساسية","en":"Sensitivity Analysis","definition":"قياس تغير النتيجة عند تغير مدخل واحد."},{"ar":"التكلفة الغارقة","en":"Sunk Cost","definition":"ما أُنفق ولا يمكن استرداده ولا يدخل في قرار المستقبل."}],"method_steps":["اكتب المعادلة قبل الأرقام (ماذا أحسب ولماذا).","وحّد الوحدات (مليون، %، شهر).","قرّب إلى أرقام سهلة ثم صحح التقريب.","احسب بصوت مسموع خطوة بخطوة.","افحص المعقولية: هل الرقم في النطاق المتوقع؟","فسّر: ماذا يعني الرقم للقرار؟","اختبر الحساسية على المدخل الأكثر شكًا."],"example_simple":{"title":"المعدل المطلوب للإنجاز","situation":"متبقٍ 5 كم من شبكة، والمدة المتبقية 6 أشهر، والمعدل الحالي 0.22 كم/شهر.","application":"المطلوب = 5 ÷ 6 = 0.83 كم/شهر. مقارنة: 0.83 ÷ 0.22 = 3.8 أضعاف المعدل الحالي. تفسير: مستحيل بالموارد الحالية؛ إما زيادة الموارد 4 أضعاف أو قبول تأخر.","result":"الرقم حوّل النقاش من «هل المقاول متأخر» إلى «كم مورد إضافي يلزم»."},"example_medium":{"title":"الرضا المرجّح","situation":"رضا الفئات 79%، 63%، 49% بأوزان زيارات 35%، 25%، 40%.","application":"0.35×79 = 27.65؛ 0.25×63 = 15.75؛ 0.40×49 = 19.6؛ المجموع 63.0%. استدلال عكسي: لبلوغ 70% مع ثبات الفئتين الأخريين، تحتاج الأحياء إلى (70 − 27.65 − 15.75) ÷ 0.4 = 66.5%.","result":"الهدف يتحقق برفع حدائق الأحياء من 49% إلى 66.5% فقط، دون لمس الكبرى."},"example_advanced":{"title":"حساسية قرار الاستمرار/الإيقاف","situation":"منافع 310 وتكلفة متبقية 215، مقابل بديل بمنافع 240 وتكلفة 130.","application":"الأساس: +95 مقابل +110. عند منافع −25%: 232.5 − 215 = +17.5 مقابل 180 − 130 = +50. عند تكلفة +15%: 310 − 247 = +63 مقابل 240 − 149.5 = +90.5. البديل يتفوق في كل السيناريوهات.","result":"القرار «مقاوم» للحساسية، فلا حاجة لدراسة أدق قبل القرار المبدئي."},"common_mistakes":["الخلط بين النقطة المئوية والنسبة المئوية.","الجمع بين وحدات مختلفة (ملايين وآلاف).","تقديم رقم دقيق دون تفسير أثره على القرار.","تجاهل التقريب المعلن ثم الخطأ بـ10%.","إدخال التكلفة الغارقة في مقارنة المستقبل."],"checklist":["هل كتبت المعادلة قبل الأرقام؟","هل الوحدات موحدة؟","هل أعلنت التقريب؟","هل فسّرت الرقم للقرار؟","هل اختبرت الحساسية على المدخل الأكثر شكًا؟"],"exercise":{"prompt":"محفظة باعتماد متبقٍ 640 مليونًا، تخفيض 18%. مشروع (أ) تكلفته 95 مليونًا وأثره 4% خفض حوادث، ومشروع (ب) 60 مليونًا وأثره 3%. احسب: المبلغ الواجب توفيره، وأثر كل مشروع لكل مليون، وأيهما أولى. (بصوت مسموع/مكتوب خطوة بخطوة)","guidance":["18% = 10% + 5% + 3% أو 20% − 2%.","الأثر لكل مليون = الأثر ÷ التكلفة.","الأولوية بالأثر لكل مليون لا بالأثر المطلق."]},"applied_case":{"title":"نقطة التعادل لمشروع مواقف ذكية","scenario":"مشروع مواقف ذكية بتكلفة 24 مليون ريال. الإيراد المتوقع 6 ريالات للساعة، والتشغيل السنوي 2.1 مليون. عدد المواقف 1,800، ومعدل الإشغال المستهدف 45% لمدة 10 ساعات يوميًا، 330 يومًا في السنة.","data":[{"label":"التكلفة الرأسمالية","value":"24 مليون"},{"label":"الإيراد للساعة","value":"6 ريال"},{"label":"التشغيل السنوي","value":"2.1 مليون"},{"label":"المواقف × الساعات × الأيام","value":"1,800 × 10 × 330"},{"label":"الإشغال المستهدف","value":"45%"}],"task":"احسب الإيراد السنوي، وصافي التدفق، وفترة الاسترداد، ثم الإشغال اللازم للاسترداد خلال 5 سنوات.","model_answer":"الساعات المتاحة = 1,800 × 10 × 330 = 5.94 مليون ساعة. بإشغال 45% = 2.673 مليون ساعة × 6 = 16.0 مليون ريال إيراد. الصافي = 16.0 − 2.1 = 13.9 مليون. الاسترداد = 24 ÷ 13.9 ≈ 1.7 سنة. للاسترداد خلال 5 سنوات يكفي صافٍ 4.8 مليون سنويًا، أي إيراد 6.9 مليون = 1.15 مليون ساعة = إشغال 19.4% فقط. التفسير: المشروع مقاوم للحساسية؛ حتى لو كان الإشغال أقل من نصف المستهدف يبقى مجديًا. المخاطر خارج الحساب: القبول المجتمعي والتحصيل الفعلي."},"result_interpretation":[{"range":"85-100","meaning":"حساباتك سريعة ودقيقة ومفسَّرة.","advice":"انتقل إلى تحليل الأسباب الجذرية."},{"range":"70-84","meaning":"دقة جيدة مع بطء أو ضعف في التفسير.","advice":"تدرب يوميًا 10 دقائق على النسب والمرجّح."},{"range":"أقل من 70","meaning":"أخطاء في الأساسيات (نقاط/نسب، وحدات).","advice":"راجع الأخطاء القاتلة وأعد التمرين."}],"next_recommendation":"وحدة «تحليل الأسباب الجذرية».","completion_rule":{"quiz_min_score":70,"applied_case_min_score":60,"description":"70% في الاختبار و60% في الحالة التطبيقية."},"primary_skill":"quantitative"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001105', '00000000-0000-4000-8000-000000000005', 'الدرس الأساسي: التحليل الكمي والحساب الذهني', '{"explanation":["في مقابلات الحالة يُقاس ليس فقط صحة الرقم بل طريقة الوصول إليه بصوت مسموع: «الاعتماد 820، التخفيض 22%، أي نحو خُمس إلا قليلًا: 820 × 0.2 = 164، زائد 820 × 0.02 = 16.4، المجموع 180.4». التفكيك إلى أجزاء سهلة (10%، 1%، 5%) هو المهارة الأساسية.","الحسابات الخمسة الأكثر تكرارًا: (1) النسبة والتغير النسبي، (2) المتوسط المرجّح، (3) القيمة لكل وحدة (لكل مليون، لكل زيارة، لكل كم)، (4) نقطة التعادل والاستدلال العكسي (كم يلزم لبلوغ الهدف؟)، (5) الحساسية (ماذا لو تغير المدخل ±25%؟).","التقريب الذكي: قرّب إلى رقم قريب سهل ثم صحح. 4.6 ÷ 9.6 ≈ 4.6 ÷ 10 = 46% ثم أضف 4% تقريبًا (لأن المقام أصغر) = 48%. القيمة الدقيقة 47.9%. الدقة المطلوبة عادة ±2% للتوصية، وصرّح بالتقريب.","أخطاء قاتلة: خلط النقاط المئوية بالنسب المئوية (من 58% إلى 70% = 12 نقطة، أي +21%)، الجمع بين قيم بوحدات مختلفة، حساب الحساسية على متغير واحد وتجاهل الآخر، ونسيان التكلفة الغارقة (أو إدخالها حين يجب استبعادها)."],"terms":[{"ar":"نقطة مئوية","en":"Percentage Point","definition":"الفرق المطلق بين نسبتين (70% − 58% = 12 نقطة)."},{"ar":"متوسط مرجّح","en":"Weighted Average","definition":"مجموع القيم × أوزانها ÷ مجموع الأوزان."},{"ar":"الاستدلال العكسي","en":"Back-solving","definition":"حساب المدخل المطلوب لبلوغ هدف محدد."},{"ar":"تحليل الحساسية","en":"Sensitivity Analysis","definition":"قياس تغير النتيجة عند تغير مدخل واحد."},{"ar":"التكلفة الغارقة","en":"Sunk Cost","definition":"ما أُنفق ولا يمكن استرداده ولا يدخل في قرار المستقبل."}],"method_steps":["اكتب المعادلة قبل الأرقام (ماذا أحسب ولماذا).","وحّد الوحدات (مليون، %، شهر).","قرّب إلى أرقام سهلة ثم صحح التقريب.","احسب بصوت مسموع خطوة بخطوة.","افحص المعقولية: هل الرقم في النطاق المتوقع؟","فسّر: ماذا يعني الرقم للقرار؟","اختبر الحساسية على المدخل الأكثر شكًا."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
