insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000050003', '00000000-0000-4000-8000-000000000005', 'quantitative', 'beginner', 'mcq', 'ارتفع الرضا من 58% إلى 70%. أي العبارات صحيحة؟', '[{"id":"a","text":"ارتفع 12%"},{"id":"b","text":"ارتفع 12 نقطة مئوية أي نحو 21%"},{"id":"c","text":"ارتفع 21 نقطة مئوية"},{"id":"d","text":"ارتفع 70%"}]'::jsonb, '{"option":"b"}'::jsonb, 'الفرق المطلق 12 نقطة، والنسبي 12 ÷ 58 = 20.7%.', true)
