insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000050004', '00000000-0000-4000-8000-000000000005', 'quantitative', 'beginner', 'numeric', 'مشروع (أ) تكلفته 95 مليونًا وأثره 4% خفض حوادث. ما الأثر لكل مليون (% لكل مليون) بأربع منازل عشرية؟', '[]'::jsonb, '{"value":0.0421,"tolerance":0.0005}'::jsonb, '4 ÷ 95 = 0.0421% لكل مليون.', true)
