insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000050005', '00000000-0000-4000-8000-000000000005', 'quantitative', 'beginner', 'table_reading', 'من الجدول، أي مشروع يحقق أعلى أثر وصول لكل مليون؟', '{"table":{"columns":["المشروع","التكلفة (مليون)","أثر الوصول (نقطة)"],"rows":[["م1",210,3],["م2",180,1],["م4",160,5],["م6",110,0]]},"choices":[{"id":"a","text":"م1"},{"id":"b","text":"م2"},{"id":"c","text":"م4"},{"id":"d","text":"م6"}]}'::jsonb, '{"option":"c"}'::jsonb, 'م4: 5 ÷ 160 = 0.031؛ م1: 0.014؛ م2: 0.006؛ م6: 0.', true)
