insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000050006', '00000000-0000-4000-8000-000000000005', 'quantitative', 'beginner', 'numeric', 'منافع مشروع 310 مليون وتكلفة متبقية 215. عند انخفاض المنافع 25%، ما صافي القيمة بالمليون؟', '[]'::jsonb, '{"value":17.5,"tolerance":0.5}'::jsonb, '310 × 0.75 = 232.5؛ 232.5 − 215 = 17.5.', true)
