insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000050007', '00000000-0000-4000-8000-000000000005', 'quantitative', 'beginner', 'spot_error', '«أنفقنا 244 مليونًا، والمتبقي 215، والمنافع 310، إذن صافي القيمة = 310 − 244 − 215 = −149، فالمشروع خاسر ويجب إيقافه». ما الخطأ؟', '[{"id":"a","text":"الجمع خاطئ"},{"id":"b","text":"أُدخلت التكلفة الغارقة (244) في قرار مستقبلي؛ الصحيح 310 − 215 = +95"},{"id":"c","text":"يجب إضافة تكلفة الإغلاق"},{"id":"d","text":"لا خطأ"}]'::jsonb, '{"option":"b"}'::jsonb, 'المنصرف لا يُسترد في أي خيار، فلا يدخل في المقارنة بين الخيارات.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000006', 'root-cause-analysis', 'تحليل الأسباب الجذرية', 'من العرض إلى السبب القابل للمعالجة: لماذا الخمسة، عظمة السمكة، تحليل الفجوات والاتجاهات، والتمييز بين الارتباط والسببية.', 'intermediate', 6, '{"learning_objective":"تصل من عرض مقاس إلى سبب جذري واحد أو اثنين مدعومين بالبيانات، وتميّز بين الارتباط والسببية، وتحلل الفجوة (الهدف مقابل الفعلي) والاتجاه (هل المشكلة تتفاقم؟) قبل اقتراح العلاج.","explanation":["السبب الجذري هو أبعد نقطة في سلسلة الأسباب يمكن للجهة التأثير فيها بتكلفة معقولة. «الأمطار» ليست سببًا جذريًا لغمر الشوارع لأنك لا تتحكم فيها؛ «عدم تنظيف المصارف قبل الموسم» سبب جذري لأنه قابل للمعالجة.","أداة «لماذا الخمسة»: اسأل لماذا خمس مرات متتالية مع التحقق ببيان في كل خطوة. الخطر: الانزلاق إلى تفسير واحد خطي بينما المشكلة لها سببان متوازيان. لذلك تُستخدم مع شجرة القضايا لا بدلًا منها.","تحليل الفجوة: الفجوة = الهدف − الفعلي، ثم تُفكك إلى مكونات (بالفئة، بالمرحلة، بالمنطقة) لمعرفة أين تتركز. تحليل الاتجاه: هل الفجوة تتسع أم تثبت أم تضيق؟ نقطة الانعطاف الزمنية (متى بدأ التغير؟) غالبًا تشير مباشرة إلى السبب (تغيير مقاول، سياسة، موسم).","الارتباط ليس سببية: زيادة الميزانية تزامنت مع تراجع الرضا، لكن السبب هو توجيه الزيادة لا الزيادة نفسها. اختبارات السببية العملية: التسلسل الزمني (السبب قبل الأثر)، الآلية المعقولة، ثبات العلاقة عبر الفئات، وغياب تفسير ثالث."],"terms":[{"ar":"السبب الجذري","en":"Root Cause","definition":"أبعد سبب قابل للتأثير فيه بتكلفة معقولة."},{"ar":"لماذا الخمسة","en":"5 Whys","definition":"سلسلة أسئلة «لماذا» مع تحقق ببيان في كل خطوة."},{"ar":"تحليل الفجوة","en":"Gap Analysis","definition":"تفكيك الفرق بين الهدف والفعلي إلى مكونات."},{"ar":"نقطة الانعطاف","en":"Inflection Point","definition":"اللحظة الزمنية التي تغير فيها الاتجاه."},{"ar":"الارتباط مقابل السببية","en":"Correlation vs Causation","definition":"تزامن حدثين لا يعني أن أحدهما سبب الآخر."}],"method_steps":["قِس العرض بدقة (كم؟ منذ متى؟ أين؟).","حلل الاتجاه وحدد نقطة الانعطاف.","فكك الفجوة إلى مكونات واعثر على التركّز.","طبّق «لماذا» مع بيان لكل خطوة حتى تصل إلى سبب قابل للمعالجة.","اختبر السببية: تسلسل، آلية، ثبات، تفسير ثالث.","تحقق من أن معالجة السبب تزيل العرض (تجربة أو مقارنة)."],"example_simple":{"title":"تكرار أعطال الإنارة","situation":"الأعطال ارتفعت 39% في عام.","application":"لماذا؟ الأعطال تتركز في 3 أحياء (تفكيك). لماذا؟ الأعمدة هناك عمرها > 15 سنة. لماذا لم تُستبدل؟ خطة الاستبدال أُجلت عامين لتمويل مهرجانات. السبب الجذري: قرار تأجيل الاستبدال — قابل للمعالجة.","result":"التوصية: برنامج استبدال مرحلي بدل زيادة ميزانية الصيانة التصحيحية."},"example_medium":{"title":"نقطة انعطاف في معدل التنفيذ","situation":"معدل تنفيذ شبكة تصريف انخفض من 0.55 إلى 0.22 كم/شهر.","application":"الاتجاه: انخفاض حاد بدأ في الشهر السابع تحديدًا. ما الذي تغير حينها؟ سجل المعدات: نقل حفارتين. التصاريح: صدرت قبل ذلك. السببية: التسلسل الزمني والآلية (معدات أقل → إنتاجية أقل) ثابتة.","result":"نقطة الانعطاف أسقطت تفسير التصاريح في دقيقتين."},"example_advanced":{"title":"تعثر متعدد الأسباب في محفظة","situation":"34 مشروعًا متعثرًا بأسباب مختلفة.","application":"التفكيك: نطاق 38%، قرارات 29%، نقل خدمات 21%، مقاول 12%. لماذا الخمسة لكل فرع بالتوازي: النطاق → لا بوابة اعتماد؛ القرارات → لا مالك للتصعيد؛ نقل الخدمات → لا مسار مبكر مع الجهات الخدمية. ثلاثة أسباب جذرية تجتمع تحت «حوكمة غير منفذة» لكن علاج كل منها مختلف.","result":"خطة بثلاث آليات بدل حل واحد عام."},"common_mistakes":["التوقف عند سبب خارج السيطرة (الطقس، السوق).","لماذا الخمسة بلا بيانات (سلسلة تخمينات).","افتراض سبب واحد لمشكلة متعددة الأسباب.","الخلط بين الارتباط والسببية.","تجاهل نقطة الانعطاف الزمنية."],"checklist":["هل قست العرض وحددت متى بدأ؟","هل فككت الفجوة ووجدت التركّز؟","هل لكل «لماذا» بيان؟","هل السبب الجذري قابل للمعالجة؟","هل اختبرت السببية (تسلسل، آلية، ثبات)؟"],"exercise":{"prompt":"ارتفعت مطالبات المقاولين في محفظة الجسور 3 أضعاف خلال عامين. طبّق «لماذا الخمسة» مع تحديد البيان الذي تطلبه في كل خطوة، ثم اذكر سببًا جذريًا واحدًا قابلًا للمعالجة.","guidance":["ابدأ بتفكيك المطالبات: بالنوع (تمديد زمن، تكلفة)، بالسبب المعلن.","ابحث عن نقطة الانعطاف: هل تزامنت مع تغيير في العقود أو الإشراف؟","توقف عند سبب داخلي قابل للمعالجة."]},"applied_case":{"title":"تراجع نسبة الالتزام بمواعيد الصيانة الوقائية","scenario":"انخفضت نسبة تنفيذ الصيانة الوقائية في الموعد من 91% إلى 64% خلال 9 أشهر في إدارة مرافق حضرية. مدير الإدارة يقول إن السبب نقص الفنيين.","data":[{"label":"الالتزام الشهري","value":"91، 90، 89، 88، 71، 68, 66، 65، 64%"},{"label":"عدد الفنيين","value":"ثابت: 24"},{"label":"ما الذي تغير في الشهر الخامس","value":"إطلاق نظام بلاغات جديد حوّل 40% من طاقة الفنيين إلى الصيانة التصحيحية"},{"label":"أوامر الصيانة الوقائية الشهرية","value":"ثابتة: 520"},{"label":"البلاغات التصحيحية","value":"ارتفعت من 310 إلى 640 شهريًا"}],"task":"حلل الاتجاه ونقطة الانعطاف، واختبر فرضية المدير، وحدد السبب الجذري القابل للمعالجة.","model_answer":"الاتجاه: انخفاض حاد بين الشهرين الرابع والخامس (88% → 71%) ثم استقرار حول 65%. نقطة الانعطاف تتزامن مع نظام البلاغات الجديد لا مع تغير في الفنيين (ثابتون 24)، فتسقط فرضية نقص الفنيين كسبب أول. الآلية: البلاغات التصحيحية تضاعفت (310 → 640) وسحبت 40% من الطاقة من الوقائية. السبب الجذري القابل للمعالجة: غياب قاعدة تخصيص طاقة محمية للصيانة الوقائية عند إطلاق قنوات بلاغات جديدة. لكن يجب التحقق من تفسير ثالث: هل زيادة البلاغات حقيقية أم نتيجة سهولة الإبلاغ (بلاغات مكررة)؟ التوصية: حجز 60% من الطاقة للوقائية، وفلترة التكرار في النظام، ومراقبة عودة الالتزام إلى > 85% خلال شهرين."},"result_interpretation":[{"range":"85-100","meaning":"تصل إلى أسباب جذرية مدعومة بالبيانات وتختبر السببية.","advice":"انتقل إلى الأولويات والمفاضلات."},{"range":"70-84","meaning":"تحليل جيد مع توقف مبكر أو إغفال تفسير ثالث.","advice":"أضف خطوة «التفسير الثالث» لكل سبب."},{"range":"أقل من 70","meaning":"الأسباب تخمينية أو خارج السيطرة.","advice":"أعد التمرين مع بيان لكل «لماذا»."}],"next_recommendation":"وحدة «تحديد الأولويات والمفاضلات».","completion_rule":{"quiz_min_score":70,"applied_case_min_score":60,"description":"70% في الاختبار و60% في الحالة التطبيقية."},"primary_skill":"root_cause"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001106', '00000000-0000-4000-8000-000000000006', 'الدرس الأساسي: تحليل الأسباب الجذرية', '{"explanation":["السبب الجذري هو أبعد نقطة في سلسلة الأسباب يمكن للجهة التأثير فيها بتكلفة معقولة. «الأمطار» ليست سببًا جذريًا لغمر الشوارع لأنك لا تتحكم فيها؛ «عدم تنظيف المصارف قبل الموسم» سبب جذري لأنه قابل للمعالجة.","أداة «لماذا الخمسة»: اسأل لماذا خمس مرات متتالية مع التحقق ببيان في كل خطوة. الخطر: الانزلاق إلى تفسير واحد خطي بينما المشكلة لها سببان متوازيان. لذلك تُستخدم مع شجرة القضايا لا بدلًا منها.","تحليل الفجوة: الفجوة = الهدف − الفعلي، ثم تُفكك إلى مكونات (بالفئة، بالمرحلة، بالمنطقة) لمعرفة أين تتركز. تحليل الاتجاه: هل الفجوة تتسع أم تثبت أم تضيق؟ نقطة الانعطاف الزمنية (متى بدأ التغير؟) غالبًا تشير مباشرة إلى السبب (تغيير مقاول، سياسة، موسم).","الارتباط ليس سببية: زيادة الميزانية تزامنت مع تراجع الرضا، لكن السبب هو توجيه الزيادة لا الزيادة نفسها. اختبارات السببية العملية: التسلسل الزمني (السبب قبل الأثر)، الآلية المعقولة، ثبات العلاقة عبر الفئات، وغياب تفسير ثالث."],"terms":[{"ar":"السبب الجذري","en":"Root Cause","definition":"أبعد سبب قابل للتأثير فيه بتكلفة معقولة."},{"ar":"لماذا الخمسة","en":"5 Whys","definition":"سلسلة أسئلة «لماذا» مع تحقق ببيان في كل خطوة."},{"ar":"تحليل الفجوة","en":"Gap Analysis","definition":"تفكيك الفرق بين الهدف والفعلي إلى مكونات."},{"ar":"نقطة الانعطاف","en":"Inflection Point","definition":"اللحظة الزمنية التي تغير فيها الاتجاه."},{"ar":"الارتباط مقابل السببية","en":"Correlation vs Causation","definition":"تزامن حدثين لا يعني أن أحدهما سبب الآخر."}],"method_steps":["قِس العرض بدقة (كم؟ منذ متى؟ أين؟).","حلل الاتجاه وحدد نقطة الانعطاف.","فكك الفجوة إلى مكونات واعثر على التركّز.","طبّق «لماذا» مع بيان لكل خطوة حتى تصل إلى سبب قابل للمعالجة.","اختبر السببية: تسلسل، آلية، ثبات، تفسير ثالث.","تحقق من أن معالجة السبب تزيل العرض (تجربة أو مقارنة)."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000060001', '00000000-0000-4000-8000-000000000006', 'root_cause', 'intermediate', 'mcq', 'أي مما يلي «سبب جذري» صالح لغمر الشوارع في موسم الأمطار؟', '[{"id":"a","text":"الأمطار الغزيرة"},{"id":"b","text":"تراجع نسبة تنظيف المصارف قبل الموسم من 88% إلى 42% بسبب تأخر ترسية عقد التنظيف"},{"id":"c","text":"المدينة في منطقة منخفضة"},{"id":"d","text":"السكان يرمون المخلفات"}]'::jsonb, '{"option":"b"}'::jsonb, 'الخيار (ب) داخلي وقابل للمعالجة ومقاس؛ (أ) و(ج) خارج السيطرة، (د) عامل مساعد غير مقاس.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000060002', '00000000-0000-4000-8000-000000000006', 'root_cause', 'intermediate', 'table_reading', 'من سلسلة الالتزام الشهري في الجدول، في أي شهر وقعت نقطة الانعطاف؟', '{"table":{"columns":["الشهر","1","2","3","4","5","6","7"],"rows":[["الالتزام %",91,90,89,88,71,68,66]]},"choices":[{"id":"a","text":"الشهر 2"},{"id":"b","text":"الشهر 4"},{"id":"c","text":"الشهر 5"},{"id":"d","text":"الشهر 7"}]}'::jsonb, '{"option":"c"}'::jsonb, 'الانخفاض الحاد (17 نقطة) حدث بين الشهرين 4 و5؛ التغير الذي وقع في الشهر 5 هو المرشح الأول للسبب.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000060003', '00000000-0000-4000-8000-000000000006', 'root_cause', 'intermediate', 'true_false', 'إذا تزامنت زيادة الميزانية مع تراجع الرضا فإن زيادة الميزانية سبب التراجع.', '[]'::jsonb, '{"value":false}'::jsonb, 'تزامن لا سببية؛ السبب قد يكون توجيه الزيادة (لفئة غير المتضررين) لا الزيادة نفسها.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000060004', '00000000-0000-4000-8000-000000000006', 'root_cause', 'intermediate', 'ordering', 'رتب خطوات تحليل السبب الجذري.', '[{"id":"s1","text":"قياس العرض وتحديد بدايته"},{"id":"s2","text":"اختبار السببية (تسلسل، آلية، ثبات)"},{"id":"s3","text":"تفكيك الفجوة وإيجاد التركّز"},{"id":"s4","text":"لماذا متسلسلة مع بيان لكل خطوة"},{"id":"s5","text":"التحقق من أن معالجة السبب تزيل العرض"}]'::jsonb, '{"order":["s1","s3","s4","s2","s5"]}'::jsonb, 'قياس ← تفكيك ← لماذا ← اختبار السببية ← تحقق.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000060005', '00000000-0000-4000-8000-000000000006', 'root_cause', 'intermediate', 'spot_error', '«لماذا تأخر المشروع؟ لأن المقاول بطيء. لماذا؟ لأنه غير كفء. لماذا؟ لأنه اختير بأقل سعر. إذن السبب الجذري: نظام المناقصات». ما الخطأ؟', '[{"id":"a","text":"عدد «لماذا» أقل من خمسة"},{"id":"b","text":"سلسلة تخمينات بلا بيان في أي خطوة، وقفزت إلى سبب نظامي دون استبعاد أسباب أخرى (نطاق، تصاريح، موارد)"},{"id":"c","text":"السبب الجذري يجب أن يكون المقاول"},{"id":"d","text":"لا خطأ"}]'::jsonb, '{"option":"b"}'::jsonb, 'كل خطوة تحتاج بيانًا (هل المقاول نفسه بطيء في مشاريع أخرى؟ ما توزيع أسباب التأخر؟).', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000060006', '00000000-0000-4000-8000-000000000006', 'root_cause', 'intermediate', 'numeric', 'الفجوة عن هدف الرضا 70%: الفئات كبرى 79% (وزن 35%)، متوسطة 63% (25%)، أحياء 49% (40%). ما مساهمة حدائق الأحياء في الفجوة بالنقاط المرجّحة (وزن × (70 − رضا)) بمنزلة عشرية واحدة؟', '[]'::jsonb, '{"value":8.4,"tolerance":0.2}'::jsonb, '0.40 × (70 − 49) = 8.4 نقطة، مقابل 1.75 للمتوسطة و0 للكبرى (فوق الهدف).', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000007', 'prioritization-tradeoffs', 'تحديد الأولويات والمفاضلات', 'المقارنة بين البدائل بمعايير صريحة، وإظهار ما يُضحّى به، وتحليل السيناريوهات والحساسية قبل التوصية.', 'intermediate', 7, '{"learning_objective":"تقارن البدائل بمعايير موزونة مرتبطة بأهداف صاحب القرار، وتصرّح بالمفاضلة (ما الذي نخسره)، وتبني سيناريوهين على الأقل مع تحليل حساسية على المدخل الأكثر شكًا.","explanation":["التوصية بلا مفاضلة ليست توصية. صاحب القرار يعرف أن كل خيار له ثمن؛ ما يريده منك هو تسمية الثمن ومقارنته بالعائد. «نوصي بالخيار (ب) لأنه يحقق هدف السلامة بـ70% من التكلفة، مقابل تأجيل هدف الوصول 8 أشهر» أفضل من «نوصي بالخيار (ب) لأنه الأفضل».","مصفوفة المعايير: اختر 3-5 معايير من أهداف صاحب القرار (لا من خيالك)، أعطها أوزانًا تجمع إلى 100، وقيّم كل بديل من 1-5. النتيجة توجيهية لا نهائية؛ الأهم أن تكشف أين يتفوق كل بديل. الخطأ الشائع: معايير كثيرة بأوزان متساوية تجعل كل شيء متعادلًا.","الأولوية بالأثر لكل وحدة مورد (لكل مليون، لكل شهر، لكل موظف) هي المعيار الأكثر دفاعًا في القطاع الحكومي، لأنها تجيب: «أين يُحدث الريال التالي أكبر فرق؟». مصفوفة الأثر/الجهد (2×2) أداة سريعة لتصنيف المبادرات: نفّذ فورًا، خطط، عوّض، استبعد.","السيناريوهات: لا تقدم رقمًا واحدًا. الأساس + متشائم + متفائل، مع تحديد المدخل الذي يميز بينها. الحساسية تجيب: هل تتغير التوصية إذا كان المدخل خاطئًا بـ25%؟ إن لم تتغير فالقرار متين؛ إن تغيرت فحدد «العتبة» التي تنقلب عندها التوصية واجعلها شرط المراقبة."],"terms":[{"ar":"المفاضلة","en":"Trade-off","definition":"ما يُضحّى به عند اختيار بديل على آخر."},{"ar":"مصفوفة المعايير الموزونة","en":"Weighted Criteria Matrix","definition":"مقارنة بدائل بمعايير لها أوزان."},{"ar":"الأثر لكل وحدة مورد","en":"Impact per Unit of Resource","definition":"العائد مقسومًا على التكلفة أو الجهد."},{"ar":"تحليل السيناريوهات","en":"Scenario Analysis","definition":"نتائج القرار تحت افتراضات بديلة متسقة."},{"ar":"عتبة الانقلاب","en":"Switching Threshold","definition":"قيمة المدخل التي تتغير عندها التوصية."}],"method_steps":["اشتق المعايير من أهداف صاحب القرار وقيوده (3-5).","أعطِ أوزانًا تجمع إلى 100 مع تبرير.","قيّم البدائل وأظهر الأثر لكل وحدة مورد.","سمّ المفاضلة صراحة لكل بديل مفضل.","ابنِ سيناريوهين على الأقل واحسب النتيجة.","حدد عتبة الانقلاب واجعلها مؤشر مراقبة.","قدّم توصية واحدة مع بديل احتياطي مشروط."],"example_simple":{"title":"ثلاث مبادرات لخفض زمن الرخص","situation":"قائمة تحقق مسبقة (أثر −8 أيام، جهد أسبوعان)، نظام جديد (−15 يومًا، 9 أشهر)، تعيين موظفين (−5 أيام، شهران).","application":"الأثر لكل شهر جهد: القائمة 16 يومًا/شهر، الموظفون 2.5، النظام 1.7. مصفوفة الأثر/الجهد: القائمة «نفّذ فورًا»، النظام «خطط»، الموظفون «عوّض».","result":"البدء بالقائمة يحقق نصف الهدف خلال أسبوعين ويشتري وقتًا لقرار النظام."},"example_medium":{"title":"السلامة مقابل رضا السكان","situation":"مشروع تقاطعات خطرة (70 مليون، −7% حوادث) مقابل حديقة مركزية (65 مليون، +6 نقاط رضا).","application":"لا يمكن مقارنة الحوادث بالرضا مباشرة؛ ارجع إلى أوزان صاحب القرار: السلامة وزن 60، الرضا 40. التقاطعات: 5×0.6 + 1×0.4 = 3.4؛ الحديقة: 1×0.6 + 5×0.4 = 2.6. المفاضلة الصريحة: تأجيل الحديقة يخفض الرضا في حي واحد لكنه يمنع نحو 9 حوادث مميتة سنويًا.","result":"التوصية بالتقاطعات مع تعويض جزئي للحي (تحسينات صغيرة بـ8 ملايين)."},"example_advanced":{"title":"سيناريوهات تمويل مشروع تطوير","situation":"ثلاثة خيارات: تمويل ذاتي، شراكة مستثمر (40% من الإيراد)، نطاق مقلّص.","application":"الأساس: +95 / +31 / +110. متشائم (منافع −25%): +17.5 / −15.5 / +50. متفائل (+15%): +141.5 / +59 / +146. النطاق المقلّص يتفوق أو يقارب في كل السيناريوهات. عتبة الانقلاب: إن كانت منافع النطاق الكامل > 350 يصبح الاستكمال أفضل.","result":"توصية متينة مع شرط مراقبة: تحديث تقدير المنافع؛ إن تجاوز 350 يُعاد النظر."},"common_mistakes":["توصية بفعل كل شيء دون ترتيب.","معايير من عند المستشار لا من أهداف صاحب القرار.","أوزان متساوية تُنتج تعادلًا بلا معنى.","رقم واحد بلا سيناريوهات.","إخفاء الثمن (المفاضلة) في التوصية."],"checklist":["هل المعايير مشتقة من أهداف صاحب القرار؟","هل الأوزان مبررة وتجمع إلى 100؟","هل حسبت الأثر لكل وحدة مورد؟","هل سميت المفاضلة صراحة؟","هل لديك سيناريوهان وعتبة انقلاب؟"],"exercise":{"prompt":"لديك 120 مليونًا وأربع مبادرات: (أ) 50 مليونًا/سلامة 5%، (ب) 40/رضا 4 نقاط، (ج) 30/سلامة 2% ورضا 2 نقاط، (د) 60/وصول 3 نقاط. أوزان صاحب القرار: سلامة 50، رضا 30، وصول 20. اختر المحفظة ضمن الميزانية وسمّ المفاضلة.","guidance":["حوّل كل أثر إلى نقاط موزونة لكل مليون.","جرّب توليفات ضمن 120 مليونًا.","ما الذي تخسره في التوليفة المختارة؟"]},"applied_case":{"title":"ترتيب أولويات صيانة الجسور","scenario":"إدارة الجسور لديها 9 جسور تحتاج صيانة بميزانية 45 مليونًا تكفي لنحو نصفها. لكل جسر: درجة حالة (1 خطر – 5 ممتاز)، حجم مرور يومي، تكلفة الصيانة.","data":[{"label":"ج1: حالة 1، مرور 85 ألف، تكلفة 14 مليون","value":""},{"label":"ج2: حالة 2، مرور 40 ألف، تكلفة 9 ملايين","value":""},{"label":"ج3: حالة 2، مرور 12 ألف، تكلفة 6 ملايين","value":""},{"label":"ج4: حالة 3، مرور 95 ألف، تكلفة 11 مليون","value":""},{"label":"ج5: حالة 2، مرور 70 ألف، تكلفة 16 مليون","value":""},{"label":"ج6-ج9: حالة 3-4، مرور 8-20 ألف، تكلفة 5-8 ملايين لكل جسر","value":""},{"label":"معيار الإدارة المعلن","value":"السلامة أولًا ثم أثر الانقطاع"}],"task":"ابنِ معيار أولوية صريحًا، رتب الجسور، اختر ما يدخل ضمن 45 مليونًا، وسمّ المفاضلة والمخاطر.","model_answer":"المعيار: درجة الخطورة = (5 − الحالة) × المرور اليومي (ألف)، ثم الأثر لكل مليون = الخطورة ÷ التكلفة. ج1: 4×85=340 ÷14 = 24.3؛ ج5: 3×70=210 ÷16 = 13.1؛ ج2: 3×40=120 ÷9 = 13.3؛ ج4: 2×95=190 ÷11 = 17.3؛ ج3: 3×12=36 ÷6 = 6. الترتيب: ج1، ج4، ج2، ج5، ج3. ضمن 45 مليونًا: ج1 (14) + ج4 (11) + ج2 (9) = 34، والمتبقي 11 لا يكفي لج5 (16) — الخيار: ج3 (6) + تدخل مؤقت لج5 (5 ملايين تدعيم) = 45. المفاضلة الصريحة: تأجيل الصيانة الكاملة لج5 (حالة 2، 70 ألف مرور) عامًا مقابل تغطية 4 جسور؛ المخاطر: تدهور ج5 — نخففه بفحص شهري وحد سرعة، ونطلب اعتمادًا تكميليًا. عتبة الانقلاب: إن انخفضت حالة ج5 إلى 1 يُقدَّم فورًا على ج2."},"result_interpretation":[{"range":"85-100","meaning":"تقارن بمعايير صاحب القرار وتسمّي المفاضلة وتبني سيناريوهات.","advice":"انتقل إلى تحليل المحافظ والبرامج."},{"range":"70-84","meaning":"الترتيب صحيح لكن المفاضلة أو الحساسية ناقصة.","advice":"أضف «ما الذي نخسره» وعتبة الانقلاب لكل توصية."},{"range":"أقل من 70","meaning":"الأولويات بلا معيار صريح.","advice":"أعد التمرين بمصفوفة معايير موزونة."}],"next_recommendation":"وحدة «تحليل المحافظ والبرامج والمشاريع».","completion_rule":{"quiz_min_score":70,"applied_case_min_score":60,"description":"70% في الاختبار و60% في الحالة التطبيقية."},"primary_skill":"prioritization"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001107', '00000000-0000-4000-8000-000000000007', 'الدرس الأساسي: تحديد الأولويات والمفاضلات', '{"explanation":["التوصية بلا مفاضلة ليست توصية. صاحب القرار يعرف أن كل خيار له ثمن؛ ما يريده منك هو تسمية الثمن ومقارنته بالعائد. «نوصي بالخيار (ب) لأنه يحقق هدف السلامة بـ70% من التكلفة، مقابل تأجيل هدف الوصول 8 أشهر» أفضل من «نوصي بالخيار (ب) لأنه الأفضل».","مصفوفة المعايير: اختر 3-5 معايير من أهداف صاحب القرار (لا من خيالك)، أعطها أوزانًا تجمع إلى 100، وقيّم كل بديل من 1-5. النتيجة توجيهية لا نهائية؛ الأهم أن تكشف أين يتفوق كل بديل. الخطأ الشائع: معايير كثيرة بأوزان متساوية تجعل كل شيء متعادلًا.","الأولوية بالأثر لكل وحدة مورد (لكل مليون، لكل شهر، لكل موظف) هي المعيار الأكثر دفاعًا في القطاع الحكومي، لأنها تجيب: «أين يُحدث الريال التالي أكبر فرق؟». مصفوفة الأثر/الجهد (2×2) أداة سريعة لتصنيف المبادرات: نفّذ فورًا، خطط، عوّض، استبعد.","السيناريوهات: لا تقدم رقمًا واحدًا. الأساس + متشائم + متفائل، مع تحديد المدخل الذي يميز بينها. الحساسية تجيب: هل تتغير التوصية إذا كان المدخل خاطئًا بـ25%؟ إن لم تتغير فالقرار متين؛ إن تغيرت فحدد «العتبة» التي تنقلب عندها التوصية واجعلها شرط المراقبة."],"terms":[{"ar":"المفاضلة","en":"Trade-off","definition":"ما يُضحّى به عند اختيار بديل على آخر."},{"ar":"مصفوفة المعايير الموزونة","en":"Weighted Criteria Matrix","definition":"مقارنة بدائل بمعايير لها أوزان."},{"ar":"الأثر لكل وحدة مورد","en":"Impact per Unit of Resource","definition":"العائد مقسومًا على التكلفة أو الجهد."},{"ar":"تحليل السيناريوهات","en":"Scenario Analysis","definition":"نتائج القرار تحت افتراضات بديلة متسقة."},{"ar":"عتبة الانقلاب","en":"Switching Threshold","definition":"قيمة المدخل التي تتغير عندها التوصية."}],"method_steps":["اشتق المعايير من أهداف صاحب القرار وقيوده (3-5).","أعطِ أوزانًا تجمع إلى 100 مع تبرير.","قيّم البدائل وأظهر الأثر لكل وحدة مورد.","سمّ المفاضلة صراحة لكل بديل مفضل.","ابنِ سيناريوهين على الأقل واحسب النتيجة.","حدد عتبة الانقلاب واجعلها مؤشر مراقبة.","قدّم توصية واحدة مع بديل احتياطي مشروط."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000070001', '00000000-0000-4000-8000-000000000007', 'prioritization', 'intermediate', 'numeric', 'مبادرة (أ): 50 مليونًا وأثر سلامة 5%. مبادرة (ج): 30 مليونًا وأثر سلامة 2%. ما نسبة أثر (أ) لكل مليون إلى أثر (ج) لكل مليون؟ (منزلتان عشريتان)', '[]'::jsonb, '{"value":1.5,"tolerance":0.02}'::jsonb, '(5/50) ÷ (2/30) = 0.10 ÷ 0.0667 = 1.5.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000070002', '00000000-0000-4000-8000-000000000007', 'prioritization', 'intermediate', 'compare_recommendations', 'أي التوصيتين أفضل ولماذا؟ (1) «نوصي بمشروع التقاطعات لأنه الأفضل». (2) «نوصي بمشروع التقاطعات: يحقق 7% خفض حوادث بـ70 مليونًا (0.1%/مليون)، مقابل تأجيل الحديقة عامًا وانخفاض متوقع 3 نقاط رضا في حي واحد، نعوضه بتحسينات بـ8 ملايين». اكتب تقييمك في 3 أسطر.', '[]'::jsonb, '{"keywords":["الثانية","مفاضلة","رقم","تعويض"],"min_matches":2}'::jsonb, 'التوصية الثانية تسمّي العائد بالأرقام والمفاضلة والتعويض؛ الأولى حكم بلا دليل.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000070003', '00000000-0000-4000-8000-000000000007', 'prioritization', 'intermediate', 'true_false', 'عند تساوي أوزان المعايير تصبح المصفوفة أكثر موضوعية.', '[]'::jsonb, '{"value":false}'::jsonb, 'الأوزان المتساوية تتجاهل أولويات صاحب القرار وغالبًا تُنتج تعادلًا بلا معنى.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000070004', '00000000-0000-4000-8000-000000000007', 'prioritization', 'intermediate', 'mcq', 'توصيتك بالبديل (ب) تعتمد على منافع مقدرة بـ240 مليونًا. عند منافع 180 يبقى (ب) أفضل، وعند 150 يصبح (أ) أفضل. ما «عتبة الانقلاب» التي يجب مراقبتها؟', '[{"id":"a","text":"240"},{"id":"b","text":"بين 150 و180"},{"id":"c","text":"180"},{"id":"d","text":"لا توجد عتبة"}]'::jsonb, '{"option":"b"}'::jsonb, 'التوصية تنقلب عند قيمة بين 150 و180؛ يجب حسابها بدقة وجعلها شرط مراقبة.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000070005', '00000000-0000-4000-8000-000000000007', 'prioritization', 'intermediate', 'ordering', 'رتب المشاريع بالأثر لكل مليون (الأعلى أولًا): م1 (210 مليون، سلامة 6%)، م5 (70، 7%)، م4 (160، 2%)، م2 (180، 5%).', '[{"id":"m1","text":"م1"},{"id":"m5","text":"م5"},{"id":"m4","text":"م4"},{"id":"m2","text":"م2"}]'::jsonb, '{"order":["m5","m1","m2","m4"]}'::jsonb, 'م5: 0.100؛ م1: 0.029؛ م2: 0.028؛ م4: 0.0125 (% لكل مليون).', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000070006', '00000000-0000-4000-8000-000000000007', 'prioritization', 'intermediate', 'written_recommendation', 'لديك 45 مليونًا لصيانة جسور: ج1 (حالة 1، 85 ألف مرور، 14 مليون)، ج4 (حالة 3، 95 ألف، 11)، ج2 (حالة 2، 40 ألف، 9)، ج5 (حالة 2، 70 ألف، 16). اكتب توصية من 4 أسطر تبدأ بالقرار وتسمّي المفاضلة.', '[]'::jsonb, '{"keywords":["نوصي","ج1","مفاضلة","تأجيل","مليون"],"min_matches":3}'::jsonb, 'نموذج: نوصي بج1 وج4 وج2 (34 مليونًا) وتدعيم مؤقت لج5؛ المفاضلة: تأجيل الصيانة الكاملة لج5 عامًا مع فحص شهري.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000008', 'portfolio-program-project', 'تحليل المحافظ والبرامج والمشاريع', 'تقييم المحفظة كوحدة قرار: الموازنة بين الجاري وغير المبدوء، التكلفة الغارقة، القيمة المتبقية، وبناء Business Case.', 'expert', 8, '{"learning_objective":"تقيّم محفظة مشاريع وفق أثرها على الأهداف الاستراتيجية لكل وحدة مورد، وتتعامل مع التكلفة الغارقة والقيمة المتبقية والغرامات، وتبني Business Case مختصرًا (خيارات، تكاليف، منافع، مخاطر، توصية).","explanation":["الفرق الجوهري: المشروع يُدار للتسليم (نطاق/زمن/تكلفة)، البرنامج يُدار للمنافع (مجموعة مشاريع تحقق نتيجة)، والمحفظة تُدار للقيمة والتوازن مقابل الاستراتيجية والقدرة. قرار المحفظة ليس «هل هذا المشروع جيد؟» بل «هل هذا أفضل استخدام للريال التالي مقارنة ببقية المحفظة؟».","عند تخفيض الاعتماد: صنّف المشاريع إلى جارٍ/غير مبدوء، واحسب لكل مشروع ثلاثة أرقام: التكلفة المتبقية، الأثر على كل هدف استراتيجي لكل مليون متبقٍ، وتكلفة الخروج (غرامات، إغلاق آمن، إعادة تعبئة). المنصرف تكلفة غارقة ولا يدخل في المقارنة — لكن تكلفة الخروج تدخل.","Business Case المختصر (صفحة واحدة): الحاجة (المشكلة بالأرقام)، الخيارات (بما فيها «لا شيء»)، التكاليف الكاملة (رأسمالية + تشغيلية 10 سنوات)، المنافع (كمية ونوعية، مع مصدر التقدير)، المخاطر والافتراضات، التوصية والخطوة التالية. القيمة الحالية الصافية أو فترة الاسترداد أو الأثر لكل مليون بحسب ما يفهمه صاحب القرار.","الاعتماديات بين المشاريع تُغير الحساب: مشروع الطريق بلا مشروع الجسر لا يحقق أثر الوصول. لذا تُقيَّم «الحزم» لا المشاريع المنفردة عند وجود اعتمادية قوية. ومخاطر المحفظة (مقاول واحد في 5 مشاريع، تمويل مشروط) تُدار على مستوى المحفظة لا كل مشروع."],"terms":[{"ar":"المحفظة","en":"Portfolio","definition":"مجموعة مشاريع وبرامج تُدار معًا لتحقيق أهداف استراتيجية ضمن قدرة محدودة."},{"ar":"البرنامج","en":"Program","definition":"مشاريع مترابطة تُدار معًا لتحقيق منافع لا تتحقق بإدارتها منفردة."},{"ar":"التكلفة الغارقة","en":"Sunk Cost","definition":"المنصرف غير القابل للاسترداد؛ لا يدخل في قرار المستقبل."},{"ar":"تكلفة الخروج","en":"Exit / Termination Cost","definition":"غرامات وإغلاق آمن وإعادة تعبئة عند الإيقاف."},{"ar":"دراسة الجدوى المؤسسية","en":"Business Case","definition":"وثيقة قرار: حاجة، خيارات، تكاليف، منافع، مخاطر، توصية."},{"ar":"الاعتمادية","en":"Dependency","definition":"علاقة تجعل منفعة مشروع مشروطة بإنجاز آخر."}],"method_steps":["حدد الأهداف الاستراتيجية للمحفظة ومقاييسها.","صنّف المشاريع: جارٍ/غير مبدوء، وحدد الاعتماديات.","احسب لكل مشروع: المتبقي، الأثر لكل مليون على كل هدف، تكلفة الخروج.","استبعد التكلفة الغارقة صراحة من المقارنة.","كوّن الحزم عند وجود اعتماديات.","رتب الحزم بالأثر الموزون لكل مليون وطبّق القيد المالي.","تحقق من الأهداف بعد الترتيب، وحدد مخاطر المحفظة.","اكتب Business Case من صفحة واحدة."],"example_simple":{"title":"مشروعان وميزانية لواحد","situation":"م1 لم يبدأ (100 مليون، وصول +4)، م2 جارٍ (متبقٍ 90، منصرف 60، وصول +3، غرامة إيقاف 12).","application":"الأثر لكل مليون متبقٍ: م1 0.04، م2 0.033. لكن إيقاف م2 يكلف 12 ويحرمنا 3 نقاط؛ الاستمرار في م2 يكلف 90 ويحقق 3. مقارنة الخيارين ضمن 100: (م2 فقط) 90 → +3؛ (م1 فقط) 100 + 12 غرامة = 112 > الميزانية. الخيار الوحيد الممكن: م2.","result":"التكلفة الغارقة (60) لم تدخل، لكن الغرامة (12) دخلت وغيّرت الجواب."},"example_medium":{"title":"Business Case لمواقف ذكية","situation":"24 مليونًا رأسمالية، صافي 13.9 مليون سنويًا بإشغال 45%.","application":"الخيارات: لا شيء (خسارة إيراد 0 لكن استمرار الفوضى)، مواقف ذكية، تحصيل يدوي (تكلفة أقل 8 ملايين، تسرب 30%). الاسترداد: ذكية 1.7 سنة؛ يدوية 8 ÷ (16×0.7 − 3.5) = 1.0 سنة لكن بصافي 10 سنوات أقل بـ36 مليونًا. المخاطر: القبول المجتمعي؛ الافتراض الحاكم: الإشغال ≥ 20%.","result":"التوصية بالذكية مع مرحلة تجريبية في 300 موقف."},"example_advanced":{"title":"إعادة ترتيب محفظة 12 مشروعًا تحت تخفيض 22%","situation":"7 جارية و5 لم تبدأ، هدفان استراتيجيان، اعتمادية بين طريق وجسر، مقاول واحد في 4 مشاريع.","application":"الحزم: (طريق + جسر) تُقيَّم معًا. الترتيب بالأثر الموزون لكل مليون متبقٍ مع تكلفة الخروج. مخاطر المحفظة: تركّز المقاول — إن أُوقف مشروعان له قد يتعثر الباقي؛ يُدرج كقيد. النتيجة: تأجيل 3 غير مبدوءة بأثر منخفض وتقليص نطاق مشروع جارٍ بدل إيقافه.","result":"تحقق الهدفان بـ78% من الاعتماد الأصلي."},"common_mistakes":["إدخال التكلفة الغارقة أو إغفال تكلفة الخروج.","تقييم المشاريع منفردة مع وجود اعتماديات.","المقارنة بالأثر المطلق لا لكل مليون.","Business Case بلا خيار «لا شيء» ولا تكاليف تشغيل.","تجاهل مخاطر المحفظة (تركّز مقاول، تمويل مشروط)."],"checklist":["هل استبعدت التكلفة الغارقة وأدخلت تكلفة الخروج؟","هل حسبت الأثر لكل مليون متبقٍ لكل هدف؟","هل كوّنت حزمًا للاعتماديات؟","هل تحققت من الأهداف بعد الترتيب؟","هل يتضمن Business Case خيار «لا شيء» والتكاليف الكاملة؟"],"exercise":{"prompt":"محفظة من 5 مشاريع باعتماد متبقٍ 500 مليون وتخفيض 20%. لكل مشروع: المتبقي، الأثر على السلامة والوصول، الحالة (جارٍ/لم يبدأ)، غرامة الإيقاف. صمّم جدول القرار واذكر الحزمة الموصى بها والتحقق من الهدفين.","guidance":["ابدأ بحساب المطلوب توفيره (100 مليون).","احسب صافي التوفير من الإيقاف = المتبقي − الغرامة.","رتب بالأثر لكل مليون، وتحقق من الأهداف بعد الاختيار."]},"applied_case":{"title":"الاستمرار أم التقليص: برنامج تطوير 6 حدائق","scenario":"برنامج تطوير 6 حدائق بقيمة 180 مليونًا؛ اكتملت حديقتان (منصرف 70)، وثلاث جارية (منصرف 40 من 75)، وواحدة لم تبدأ (35). ظهر عجز 45 مليونًا. هدف البرنامج: رفع رضا 5 أحياء إلى 70%.","data":[{"label":"الجارية: ح3 (متبقٍ 15، رضا +6 في حيها)، ح4 (متبقٍ 12، +5)، ح5 (متبقٍ 8، +2 — يقع في حي رضاه 74% أصلًا)","value":""},{"label":"غير المبدوءة: ح6 (35، +9 في حي رضاه 51%)","value":""},{"label":"غرامات الإيقاف","value":"ح3: 4، ح4: 3، ح5: 2 (مليون)"},{"label":"الأحياء دون 70%","value":"أحياء ح3، ح4، ح6"}],"task":"قرر ما يستمر وما يُقلَّص أو يُلغى لسد عجز 45 مليونًا مع تحقيق هدف البرنامج، واكتب Business Case مختصرًا.","model_answer":"الحاجة: عجز 45 مليونًا. الخيارات: (أ) إلغاء ح6 (توفير 35) + إيقاف ح5 (8 − 2 = 6) = 41 — لا يكفي ويحرم حي ح6 (51%) من أكبر أثر. (ب) إيقاف ح5 (صافي 6) + تقليص ح6 إلى 20 مليونًا (توفير 15) + تأجيل جزء من ح3 (توفير 10 بتقسيم مراحل) = 31؛ لا يكفي. (ج) إيقاف ح5 (6) + تقليص ح6 إلى 12 (توفير 23) + تقليص ح3 وح4 بنسبة 40% (توفير 11 − أثر محدود) = 40 + إعادة توجيه 5 من ميزانية تشغيل = 45. التوصية: الخيار (ج): يحافظ على الأثر في الأحياء الثلاثة دون 70% (ح3، ح4، ح6) ويتخلى عن ح5 الذي يخدم حيًا راضيًا أصلًا (74%). المنصرف 40 على الجارية تكلفة غارقة ولم يدخل القرار؛ الغرامات دخلت. المخاطر: مقاومة حي ح5 — التعويض بصيانة محسنة؛ ح6 المقلّص قد لا يحقق +9 كاملة (نقدر +6 وهو كافٍ لتجاوز 57%→63% ثم مرحلة ثانية). مؤشر المتابعة: رضا الأحياء الثلاثة بعد 6 أشهر من الافتتاح."},"result_interpretation":[{"range":"85-100","meaning":"تفكر على مستوى المحفظة وتتعامل مع الغارقة والخروج والاعتماديات.","advice":"انتقل إلى الحوكمة والمخاطر."},{"range":"70-84","meaning":"الحساب صحيح لكن الاعتماديات أو مخاطر المحفظة ناقصة.","advice":"أضف تحليل الاعتماديات وتركّز المخاطر لكل محفظة."},{"range":"أقل من 70","meaning":"تقيّم المشاريع منفردة أو تُدخل التكلفة الغارقة.","advice":"راجع الوحدة الخامسة (الغارقة) وأعد التمرين."}],"next_recommendation":"وحدة «الحوكمة والمخاطر والاعتماديات».","completion_rule":{"quiz_min_score":70,"applied_case_min_score":65,"description":"70% في الاختبار و65% في الحالة التطبيقية."},"primary_skill":"portfolio_evaluation"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001108', '00000000-0000-4000-8000-000000000008', 'الدرس الأساسي: تحليل المحافظ والبرامج والمشاريع', '{"explanation":["الفرق الجوهري: المشروع يُدار للتسليم (نطاق/زمن/تكلفة)، البرنامج يُدار للمنافع (مجموعة مشاريع تحقق نتيجة)، والمحفظة تُدار للقيمة والتوازن مقابل الاستراتيجية والقدرة. قرار المحفظة ليس «هل هذا المشروع جيد؟» بل «هل هذا أفضل استخدام للريال التالي مقارنة ببقية المحفظة؟».","عند تخفيض الاعتماد: صنّف المشاريع إلى جارٍ/غير مبدوء، واحسب لكل مشروع ثلاثة أرقام: التكلفة المتبقية، الأثر على كل هدف استراتيجي لكل مليون متبقٍ، وتكلفة الخروج (غرامات، إغلاق آمن، إعادة تعبئة). المنصرف تكلفة غارقة ولا يدخل في المقارنة — لكن تكلفة الخروج تدخل.","Business Case المختصر (صفحة واحدة): الحاجة (المشكلة بالأرقام)، الخيارات (بما فيها «لا شيء»)، التكاليف الكاملة (رأسمالية + تشغيلية 10 سنوات)، المنافع (كمية ونوعية، مع مصدر التقدير)، المخاطر والافتراضات، التوصية والخطوة التالية. القيمة الحالية الصافية أو فترة الاسترداد أو الأثر لكل مليون بحسب ما يفهمه صاحب القرار.","الاعتماديات بين المشاريع تُغير الحساب: مشروع الطريق بلا مشروع الجسر لا يحقق أثر الوصول. لذا تُقيَّم «الحزم» لا المشاريع المنفردة عند وجود اعتمادية قوية. ومخاطر المحفظة (مقاول واحد في 5 مشاريع، تمويل مشروط) تُدار على مستوى المحفظة لا كل مشروع."],"terms":[{"ar":"المحفظة","en":"Portfolio","definition":"مجموعة مشاريع وبرامج تُدار معًا لتحقيق أهداف استراتيجية ضمن قدرة محدودة."},{"ar":"البرنامج","en":"Program","definition":"مشاريع مترابطة تُدار معًا لتحقيق منافع لا تتحقق بإدارتها منفردة."},{"ar":"التكلفة الغارقة","en":"Sunk Cost","definition":"المنصرف غير القابل للاسترداد؛ لا يدخل في قرار المستقبل."},{"ar":"تكلفة الخروج","en":"Exit / Termination Cost","definition":"غرامات وإغلاق آمن وإعادة تعبئة عند الإيقاف."},{"ar":"دراسة الجدوى المؤسسية","en":"Business Case","definition":"وثيقة قرار: حاجة، خيارات، تكاليف، منافع، مخاطر، توصية."},{"ar":"الاعتمادية","en":"Dependency","definition":"علاقة تجعل منفعة مشروع مشروطة بإنجاز آخر."}],"method_steps":["حدد الأهداف الاستراتيجية للمحفظة ومقاييسها.","صنّف المشاريع: جارٍ/غير مبدوء، وحدد الاعتماديات.","احسب لكل مشروع: المتبقي، الأثر لكل مليون على كل هدف، تكلفة الخروج.","استبعد التكلفة الغارقة صراحة من المقارنة.","كوّن الحزم عند وجود اعتماديات.","رتب الحزم بالأثر الموزون لكل مليون وطبّق القيد المالي.","تحقق من الأهداف بعد الترتيب، وحدد مخاطر المحفظة.","اكتب Business Case من صفحة واحدة."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000080001', '00000000-0000-4000-8000-000000000008', 'portfolio_evaluation', 'expert', 'numeric', 'مشروع جارٍ: منصرف 60، متبقٍ 90، غرامة إيقاف 12 (مليون). ما صافي التوفير من إيقافه بالمليون؟', '[]'::jsonb, '{"value":78,"tolerance":0.5}'::jsonb, '90 − 12 = 78. المنصرف 60 تكلفة غارقة لا يدخل.', true)
