insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000080002', '00000000-0000-4000-8000-000000000008', 'portfolio_evaluation', 'expert', 'matching', 'طابق المستوى بما يُدار له.', '{"left":[{"id":"l1","text":"المشروع"},{"id":"l2","text":"البرنامج"},{"id":"l3","text":"المحفظة"}],"right":[{"id":"r1","text":"التسليم ضمن نطاق وزمن وتكلفة"},{"id":"r2","text":"تحقيق منافع من مشاريع مترابطة"},{"id":"r3","text":"القيمة والتوازن مقابل الاستراتيجية والقدرة"}]}'::jsonb, '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'التمييز المعياري في P3O/PMI.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000080003', '00000000-0000-4000-8000-000000000008', 'portfolio_evaluation', 'expert', 'true_false', 'عند وجود اعتمادية قوية بين مشروعين، يجب تقييمهما كحزمة واحدة لا كمشروعين منفردين.', '[]'::jsonb, '{"value":true}'::jsonb, 'منفعة أحدهما مشروطة بالآخر؛ تقييمهما منفردين يضلل الترتيب.', true)
