insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000080004', '00000000-0000-4000-8000-000000000008', 'portfolio_evaluation', 'expert', 'spot_error', 'Business Case يعرض: خيار واحد (نظام جديد)، تكلفة رأسمالية 20 مليونًا، منافع «تحسين الكفاءة»، توصية بالمضي. ما أبرز خطأ؟', '[{"id":"a","text":"التكلفة مرتفعة"},{"id":"b","text":"لا خيارات بديلة (بما فيها «لا شيء»)، ولا تكاليف تشغيل، ولا منافع كمية بمصدر"},{"id":"c","text":"التوصية يجب أن تكون بالرفض"},{"id":"d","text":"لا خطأ"}]'::jsonb, '{"option":"b"}'::jsonb, 'Business Case بلا بدائل ولا تكاليف كاملة ولا منافع مقاسة ليس أساسًا لقرار.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000080005', '00000000-0000-4000-8000-000000000008', 'portfolio_evaluation', 'expert', 'table_reading', 'من الجدول، أي مشروع يجب إيقافه أولًا لتوفير الاعتماد بأقل خسارة أثر؟', '{"table":{"columns":["المشروع","المتبقي (مليون)","الأثر (نقاط)","غرامة الإيقاف"],"rows":[["أ",80,6,10],["ب",60,1,4],["ج",40,4,2],["د",100,8,0]]},"choices":[{"id":"a","text":"أ"},{"id":"b","text":"ب"},{"id":"c","text":"ج"},{"id":"d","text":"د"}]}'::jsonb, '{"option":"b"}'::jsonb, 'الأثر المفقود لكل مليون توفير صافٍ: ب = 1 ÷ 56 = 0.018 (الأدنى)؛ ج 0.105؛ أ 0.086؛ د 0.08.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000080006', '00000000-0000-4000-8000-000000000008', 'portfolio_evaluation', 'expert', 'open_analysis', 'برنامج من 4 مشاريع بعجز 30 مليونًا. اكتب منهجك في 5 خطوات لتحديد ما يُقلَّص أو يُلغى، مع ذكر كيف تتعامل مع المنصرف والغرامات والاعتماديات.', '[]'::jsonb, '{"keywords":["غارقة","غرامة","لكل مليون","اعتمادية","هدف"],"min_matches":3}'::jsonb, 'المنهج: توفير مطلوب ← استبعاد الغارقة وإدخال الغرامات ← أثر لكل مليون ← حزم للاعتماديات ← تحقق من الهدف.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000009', 'governance-risk-dependencies', 'الحوكمة والمخاطر والاعتماديات', 'تصميم بوابات مرحلية وآليات تصعيد، وتحليل المخاطر المترابطة والاعتماديات على مستوى المشروع والمحفظة، وتحويل التوصية إلى تنفيذ.', 'expert', 9, '{"learning_objective":"تصمم حوكمة قابلة للتنفيذ (من يقرر ماذا ومتى وبأي عتبة)، وتحلل المخاطر بالاحتمال والأثر والترابط، وتحدد الاعتماديات الحرجة، وتحوّل التوصية إلى خطة تنفيذ بمالك ومؤشر لكل إجراء.","explanation":["الحوكمة ليست لجانًا بل قرارات: لكل قرار متكرر (تغيير نطاق، تجاوز تكلفة، تأخر) يجب أن يُعرف مالكه وعتبته وزمنه. مثال: تغيير نطاق ≤ 5% يقرره مدير المشروع خلال 5 أيام؛ 5-15% لجنة المحفظة خلال 10 أيام؛ > 15% نائب الأمين. غياب العتبة يعني أن كل شيء يُرفع للأعلى وتصبح القيادة عنق زجاجة (47 يومًا).","بوابات Stage-Gate: نقاط قرار إلزامية بين المراحل (فكرة → جدوى → تصميم → طرح → تنفيذ → تسليم) بمعايير خروج مكتوبة. البوابة الجيدة تسمح بثلاثة قرارات: مضي، إعادة عمل، إيقاف. البوابة التي لا يُوقف فيها شيء أبدًا ليست بوابة بل ختم.","المخاطر تُقيَّم بالاحتمال × الأثر، لكن في المحافظ الأهم هو الترابط: مخاطر يشتركان في سبب واحد (مقاول واحد، جهة خدمية واحدة، تمويل مشروط) تتحقق معًا. خريطة الترابط تكشف «المخاطر النظامية» التي تحتاج استجابة على مستوى المحفظة (تنويع المقاولين، اتفاقية مستوى خدمة مع الجهة الخدمية).","الاعتماديات الحرجة: نقل الخدمات (كهرباء، مياه، اتصالات) هو المثال الأكثر تكرارًا في مشاريع الطرق؛ يقع على المسار الحرج ولا تملكه الجهة. الاستجابة: مسار مبكر موازٍ (Early Works)، اتفاقية مستوى خدمة، واحتياطي زمني صريح. خطة التنفيذ: لكل إجراء مالك وموعد ومؤشر وعتبة تصعيد."],"terms":[{"ar":"بوابة مرحلية","en":"Stage-Gate","definition":"نقطة قرار إلزامية بين مراحل بمعايير خروج مكتوبة."},{"ar":"عتبة التصعيد","en":"Escalation Threshold","definition":"القيمة التي ينتقل عندها القرار إلى مستوى أعلى."},{"ar":"المسار الحرج","en":"Critical Path","definition":"سلسلة الأنشطة التي يؤخر تأخر أي منها المشروع كله."},{"ar":"المخاطر المترابطة","en":"Correlated Risks","definition":"مخاطر تتحقق معًا لاشتراكها في سبب."},{"ar":"اتفاقية مستوى الخدمة","en":"SLA","definition":"التزام مكتوب بزمن أو جودة استجابة بين جهتين."},{"ar":"سجل المخاطر","en":"Risk Register","definition":"قائمة المخاطر بالاحتمال والأثر والمالك والاستجابة."}],"method_steps":["احصر القرارات المتكررة وحدد لكل منها: المالك، العتبة، الزمن.","صمّم البوابات بمعايير خروج قابلة للتحقق وقرارات ثلاثة (مضي/إعادة/إيقاف).","ابنِ سجل مخاطر بالاحتمال والأثر والمالك.","ارسم خريطة الترابط: أي المخاطر تشترك في سبب؟","حدد الاعتماديات الخارجية على المسار الحرج وصمّم لها SLA ومسارًا مبكرًا.","حوّل التوصية إلى خطة: إجراء، مالك، موعد، مؤشر، عتبة تصعيد.","حدد إيقاع المراجعة (أسبوعي للتصعيد، ربع سنوي للبوابات)."],"example_simple":{"title":"عتبة تغيير النطاق","situation":"72% من تغييرات النطاق تصدر بعد التنفيذ ويُرفع كل تغيير للرئيس.","application":"عتبات: ≤ 5% مدير المشروع (5 أيام)، 5-15% لجنة المحفظة (10 أيام)، > 15% الرئيس مع دراسة أثر. بوابة «تجميد التصميم» قبل الطرح: أي تغيير بعدها يحمل تكلفة إعادة تصميم موثقة.","result":"زمن القرار انخفض من 47 إلى 9 أيام وانخفضت التغييرات 40%."},"example_medium":{"title":"مخاطر مترابطة في محفظة طرق","situation":"مقاول واحد ينفذ 4 من 6 مشاريع، وجهة اتصالات واحدة تملك تصاريح الحفر لكلها.","application":"خريطة الترابط تكشف خطرين نظاميين: تعثر المقاول يضرب 65% من المحفظة؛ تأخر التصاريح يضرب 100%. الاستجابة على مستوى المحفظة: سقف 40% لأي مقاول في الطرح القادم، وSLA 15 يومًا مع جهة الاتصالات موقّع على مستوى الأمانة.","result":"تحوّلت المخاطر من 12 بندًا مكررًا إلى استجابتين محفظيتين."},"example_advanced":{"title":"خطة 100 يوم لمحفظة متعثرة","situation":"40% تعثر، لا بوابات، تصعيد 47 يومًا.","application":"الأيام 1-30: ميثاق PMO، تعيين ملاك القرارات والعتبات، لجنة تصعيد أسبوعية. 31-60: بوابة تجميد تصميم وبوابة تغيير نطاق، سجل مخاطر محفظي، SLA مع 3 جهات خدمية. 61-100: مراجعة 34 مشروعًا متعثرًا ببوابة «استمرار/تقليص/إيقاف»، لوحة تصعيد. مؤشرات: زمن التصعيد ≤ 10 أيام، تغييرات النطاق بعد التنفيذ ≤ 30%.","result":"خطة بمالك ومؤشر لكل بند بدل توصية عامة بـ«تحسين الحوكمة»."},"common_mistakes":["ذكر «الحوكمة» و«المخاطر» كمصطلحات بلا مالك أو عتبة.","بوابات لا تُوقف شيئًا.","سجل مخاطر مكرر لكل مشروع دون خريطة ترابط.","تجاهل الاعتماديات الخارجية على المسار الحرج.","توصية بلا خطة تنفيذ ومؤشرات."],"checklist":["هل لكل قرار متكرر مالك وعتبة وزمن؟","هل للبوابة معايير خروج وقرار إيقاف ممكن؟","هل رسمت خريطة ترابط المخاطر؟","هل حددت الاعتماديات الخارجية على المسار الحرج وSLA لها؟","هل لكل إجراء مالك وموعد ومؤشر؟"],"exercise":{"prompt":"صمّم مصفوفة صلاحيات (3 مستويات × 3 أنواع قرار: تغيير نطاق، تجاوز تكلفة، تمديد زمن) لمحفظة مشاريع، مع عتبات رقمية وأزمنة قرار، وبوابتين مرحليتين بمعايير خروج.","guidance":["العتبات نسب مئوية من قيمة العقد أو المدة.","زمن القرار يجب أن يكون التزامًا (SLA داخلي).","معيار الخروج قابل للتحقق (وثيقة، توقيع، رقم)."]},"applied_case":{"title":"تأخر نقل الخدمات وأثره على المسار الحرج","scenario":"مشروع طريق بطول 14 كم مدته 24 شهرًا. نقل خطوط الكهرباء والمياه يقع على المسار الحرج في 3 قطاعات. الجهة الكهربائية تحتاج 90 يومًا من الطلب، ولم يُقدَّم الطلب إلا بعد 5 أشهر من بدء العقد. المقاول يطالب بتمديد 4 أشهر وتعويض 6 ملايين.","data":[{"label":"الاحتياطي الزمني الأصلي","value":"45 يومًا"},{"label":"زمن الجهة الكهربائية","value":"90 يومًا من الطلب"},{"label":"تاريخ تقديم الطلب","value":"الشهر 5 (كان مخططًا في الشهر 1)"},{"label":"أثر التأخر على المسار الحرج","value":"120 يومًا"},{"label":"من يملك تقديم الطلب","value":"الجهة (إدارة المشروع) لا المقاول"},{"label":"المشاريع الأخرى المتأثرة بالجهة نفسها","value":"5 مشاريع"}],"task":"حلل الاعتمادية والمسؤولية، وقيّم مطالبة المقاول، واقترح آلية حوكمة تمنع التكرار على مستوى المحفظة.","model_answer":"الاعتمادية: نقل الخدمات على المسار الحرج ومملوك للجهة؛ التأخر 120 يومًا يتجاوز الاحتياطي 45 يومًا فيولّد تأخرًا صافيًا 75 يومًا. المسؤولية: تقديم الطلب من مسؤولية الجهة، فتمديد 75 يومًا (لا 120 ولا 4 أشهر) مبرر تعاقديًا؛ التعويض 6 ملايين يُراجع بالتكاليف الفعلية المثبتة (تكاليف زمنية غير مباشرة) لا كمطلب جملة. الحوكمة: (1) بوابة «جاهزية الموقع» قبل صدور أمر المباشرة تشترط تقديم طلبات نقل الخدمات؛ (2) SLA محفظي مع الجهة الكهربائية بـ60 يومًا لـ5 مشاريع مع نقطة اتصال واحدة؛ (3) مسار أعمال مبكرة منفصل لنقل الخدمات قبل العقد الرئيس؛ (4) مؤشر: نسبة المشاريع التي قُدمت طلبات خدماتها قبل المباشرة ≥ 95%، مالك: مدير المحفظة، تصعيد أسبوعي. المخاطر المترابطة: الجهة نفسها تهدد 5 مشاريع — استجابة محفظية لا لكل مشروع."},"result_interpretation":[{"range":"85-100","meaning":"تصمم حوكمة بعتبات وملاك وتحلل الترابط والاعتماديات.","advice":"انتقل إلى Pyramid Principle والتواصل التنفيذي."},{"range":"70-84","meaning":"المخاطر جيدة لكن الحوكمة عامة بلا عتبات.","advice":"أعد كتابة كل توصية بمالك وعتبة وزمن."},{"range":"أقل من 70","meaning":"مصطلحات بلا آليات.","advice":"راجع مثال العتبات وأعد التمرين."}],"next_recommendation":"وحدة «Pyramid Principle والتواصل التنفيذي».","completion_rule":{"quiz_min_score":70,"applied_case_min_score":65,"description":"70% في الاختبار و65% في الحالة التطبيقية."},"primary_skill":"risk_governance"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001109', '00000000-0000-4000-8000-000000000009', 'الدرس الأساسي: الحوكمة والمخاطر والاعتماديات', '{"explanation":["الحوكمة ليست لجانًا بل قرارات: لكل قرار متكرر (تغيير نطاق، تجاوز تكلفة، تأخر) يجب أن يُعرف مالكه وعتبته وزمنه. مثال: تغيير نطاق ≤ 5% يقرره مدير المشروع خلال 5 أيام؛ 5-15% لجنة المحفظة خلال 10 أيام؛ > 15% نائب الأمين. غياب العتبة يعني أن كل شيء يُرفع للأعلى وتصبح القيادة عنق زجاجة (47 يومًا).","بوابات Stage-Gate: نقاط قرار إلزامية بين المراحل (فكرة → جدوى → تصميم → طرح → تنفيذ → تسليم) بمعايير خروج مكتوبة. البوابة الجيدة تسمح بثلاثة قرارات: مضي، إعادة عمل، إيقاف. البوابة التي لا يُوقف فيها شيء أبدًا ليست بوابة بل ختم.","المخاطر تُقيَّم بالاحتمال × الأثر، لكن في المحافظ الأهم هو الترابط: مخاطر يشتركان في سبب واحد (مقاول واحد، جهة خدمية واحدة، تمويل مشروط) تتحقق معًا. خريطة الترابط تكشف «المخاطر النظامية» التي تحتاج استجابة على مستوى المحفظة (تنويع المقاولين، اتفاقية مستوى خدمة مع الجهة الخدمية).","الاعتماديات الحرجة: نقل الخدمات (كهرباء، مياه، اتصالات) هو المثال الأكثر تكرارًا في مشاريع الطرق؛ يقع على المسار الحرج ولا تملكه الجهة. الاستجابة: مسار مبكر موازٍ (Early Works)، اتفاقية مستوى خدمة، واحتياطي زمني صريح. خطة التنفيذ: لكل إجراء مالك وموعد ومؤشر وعتبة تصعيد."],"terms":[{"ar":"بوابة مرحلية","en":"Stage-Gate","definition":"نقطة قرار إلزامية بين مراحل بمعايير خروج مكتوبة."},{"ar":"عتبة التصعيد","en":"Escalation Threshold","definition":"القيمة التي ينتقل عندها القرار إلى مستوى أعلى."},{"ar":"المسار الحرج","en":"Critical Path","definition":"سلسلة الأنشطة التي يؤخر تأخر أي منها المشروع كله."},{"ar":"المخاطر المترابطة","en":"Correlated Risks","definition":"مخاطر تتحقق معًا لاشتراكها في سبب."},{"ar":"اتفاقية مستوى الخدمة","en":"SLA","definition":"التزام مكتوب بزمن أو جودة استجابة بين جهتين."},{"ar":"سجل المخاطر","en":"Risk Register","definition":"قائمة المخاطر بالاحتمال والأثر والمالك والاستجابة."}],"method_steps":["احصر القرارات المتكررة وحدد لكل منها: المالك، العتبة، الزمن.","صمّم البوابات بمعايير خروج قابلة للتحقق وقرارات ثلاثة (مضي/إعادة/إيقاف).","ابنِ سجل مخاطر بالاحتمال والأثر والمالك.","ارسم خريطة الترابط: أي المخاطر تشترك في سبب؟","حدد الاعتماديات الخارجية على المسار الحرج وصمّم لها SLA ومسارًا مبكرًا.","حوّل التوصية إلى خطة: إجراء، مالك، موعد، مؤشر، عتبة تصعيد.","حدد إيقاع المراجعة (أسبوعي للتصعيد، ربع سنوي للبوابات)."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000090001', '00000000-0000-4000-8000-000000000009', 'risk_governance', 'expert', 'mcq', 'أي العبارات تصف حوكمة قابلة للتنفيذ؟', '[{"id":"a","text":"تشكيل لجنة عليا لمتابعة المشاريع"},{"id":"b","text":"تغيير النطاق ≤ 5% يقرره مدير المشروع خلال 5 أيام، 5-15% لجنة المحفظة خلال 10 أيام، > 15% نائب الأمين مع دراسة أثر"},{"id":"c","text":"تعزيز ثقافة إدارة المخاطر"},{"id":"d","text":"رفع جميع القرارات للرئيس لضمان الجودة"}]'::jsonb, '{"option":"b"}'::jsonb, 'مالك + عتبة + زمن لكل قرار. (أ) و(ج) عامة، (د) تصنع عنق زجاجة.', true)
