insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000090002', '00000000-0000-4000-8000-000000000009', 'risk_governance', 'expert', 'numeric', 'اعتمادية على المسار الحرج تأخرت 120 يومًا والاحتياطي الزمني 45 يومًا. ما التأخر الصافي للمشروع بالأيام؟', '[]'::jsonb, '{"value":75,"tolerance":0}'::jsonb, '120 − 45 = 75 يومًا.', true)
