insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000090003', '00000000-0000-4000-8000-000000000009', 'risk_governance', 'expert', 'true_false', 'البوابة المرحلية التي لم يُوقف عندها أي مشروع خلال 3 سنوات دليل على جودة المشاريع.', '[]'::jsonb, '{"value":false}'::jsonb, 'الأرجح أنها ختم لا بوابة؛ البوابة الفاعلة تنتج قرارات إعادة عمل وإيقاف أحيانًا.', true)
