insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000090004', '00000000-0000-4000-8000-000000000009', 'risk_governance', 'expert', 'most_important_data', 'لتقييم المخاطر المترابطة في محفظة طرق، أي بيانين هما الأهم؟ (اختر اثنين)', '[{"id":"a","text":"توزيع المشاريع على المقاولين"},{"id":"b","text":"ألوان اللوحات الإرشادية"},{"id":"c","text":"الجهات الخدمية المشتركة على المسار الحرج لكل مشروع"},{"id":"d","text":"عدد اجتماعات اللجنة"}]'::jsonb, '{"options":["a","c"]}'::jsonb, 'تركّز المقاول والجهة الخدمية المشتركة هما مصدرا المخاطر النظامية.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000090005', '00000000-0000-4000-8000-000000000009', 'risk_governance', 'expert', 'spot_error', '«المخاطر: تأخر، تجاوز تكلفة، مقاومة التغيير. الحوكمة: لجنة توجيهية ومكتب مشاريع.» ما الخطأ الأبرز في هذا القسم من التوصية؟', '[{"id":"a","text":"المخاطر قليلة"},{"id":"b","text":"مخاطر عامة بلا احتمال/أثر/مالك، وحوكمة هيكلية بلا عتبات أو أزمنة قرار"},{"id":"c","text":"يجب حذف مكتب المشاريع"},{"id":"d","text":"لا خطأ"}]'::jsonb, '{"option":"b"}'::jsonb, 'المصطلحات بلا آليات لا تُحتسب تطبيقًا.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000090006', '00000000-0000-4000-8000-000000000009', 'risk_governance', 'expert', 'rewrite_weak_answer', 'أعد صياغة التوصية الضعيفة: «نوصي بتحسين الحوكمة وإدارة المخاطر لتقليل التعثر» لتصبح قابلة للتنفيذ (مالك، عتبة، زمن، مؤشر).', '[]'::jsonb, '{"keywords":["عتبة","يوم","مالك","مؤشر","بوابة"],"min_matches":3}'::jsonb, 'نموذج: «نوصي ببوابة تجميد تصميم قبل الطرح، وعتبات تغيير نطاق (5%/15%) بأزمنة 5/10 أيام، ولجنة تصعيد أسبوعية يرأسها الوكيل؛ المؤشر: زمن التصعيد ≤ 10 أيام خلال 90 يومًا؛ المالك: مدير المحفظة».', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000010', 'pyramid-executive-communication', 'Pyramid Principle والتواصل التنفيذي', 'بناء الرسالة من الأعلى: التوصية أولًا، ثم الأسباب المجمّعة منطقيًا، ثم الأدلة، والتقديم للقيادات في 60-90 ثانية.', 'expert', 10, '{"learning_objective":"تصوغ توصية تنفيذية تبدأ بالجواب، تدعمها 3 أسباب مستقلة ومرتبة، وتختم بالمخاطر والخطوات، وتقدمها شفهيًا خلال 60-90 ثانية، وتجيب عن اعتراض قيادي دون فقدان البنية.","explanation":["Pyramid Principle (باربرا مينتو): ابدأ بالجواب، ثم اجمع الأسباب في مجموعات منطقية (MECE)، ثم رتبها (بالأهمية، الزمن، أو البنية)، وادعم كل سبب بدليل. القائد يقرأ من الأعلى ويتوقف عندما يقتنع؛ إن دفنت التوصية في الصفحة الخامسة فلن تُقرأ.","بنية الدقيقة الواحدة: (1) الموقف والتعقيد في جملة («تخفيض 22% يهدد هدفي السلامة والوصول»)، (2) التوصية في جملة برقم («نؤجل م6 ونوقف م3 لتوفير 191 مليونًا مع تحقيق الهدفين»)، (3) ثلاثة أسباب مرقّمة بأرقام، (4) المخاطر والخطوة التالية. 90 ثانية تكفي لهذا كله إذا حذفت كل ما لا يخدم القرار.","قاعدة «ماذا في ذلك؟» (So what?): كل رقم يجب أن يتبعه معناه للقرار. «أثر م5 0.1% لكل مليون» → «أي 3 أضعاف أي مشروع آخر، لذا يبدأ فورًا». وقاعدة «كيف تعرف؟»: كل ادعاء يتبعه دليله. الجملة التي لا تجيب عن أحد السؤالين تُحذف.","الاعتراضات: القادة يختبرون التوصية بأسئلة ضاغطة («لماذا لا نقبل عرض المستثمر؟»). الجواب الجيد: اعترف بالوجاهة، أعطِ الرقم الحاسم، أعد الربط بالتوصية. لا تدافع عن كل نقطة؛ سمّ ما يغيّر رأيك («إن رفع المستثمر الحد المضمون إلى 20 مليونًا سنويًا أعدنا الحساب»). هذا يظهر أن التوصية مبنية على منطق لا على موقف."],"terms":[{"ar":"مبدأ الهرم","en":"Pyramid Principle","definition":"الجواب أولًا ثم الأسباب المجمّعة ثم الأدلة."},{"ar":"الموقف-التعقيد-السؤال-الجواب","en":"SCQA","definition":"افتتاحية تضع السياق قبل التوصية في جملتين."},{"ar":"ماذا في ذلك؟","en":"So What?","definition":"اختبار أن كل رقم يتبعه معناه للقرار."},{"ar":"التجميع المنطقي","en":"Logical Grouping","definition":"ضم الأسباب في مجموعات MECE مرتبة."},{"ar":"الملخص التنفيذي","en":"Executive Summary","definition":"صفحة واحدة تحمل التوصية والأسباب والخطوة التالية."}],"method_steps":["اكتب التوصية في جملة واحدة برقم حاسم.","اكتب كل الأسباب ثم اجمعها في 3 مجموعات MECE.","رتب المجموعات بالأهمية لصاحب القرار.","لكل سبب: دليل رقمي واحد + «ماذا في ذلك».","أضف المفاضلة والمخاطر في جملتين.","اختم بالخطوة التالية ومن يملكها ومتى.","اقرأها بصوت عالٍ وقِس الزمن: احذف حتى تبلغ 90 ثانية."],"example_simple":{"title":"توصية بخطة تعافٍ","situation":"مشروع تصريف متأخر بسبب نقص معدات.","application":"«السبب الجذري نقص المعدات لا التصاريح؛ نوصي بطلب خطة تعافٍ تعيد الحفارات إلى 4 خلال أسبوعين. لأن: (1) معدل التنفيذ انخفض 60% مع انخفاض الحفارات للنصف؛ (2) 7 من 8 تصاريح صادرة؛ (3) المطلوب 0.83 كم/شهر مستحيل بحفارتين. الخطر: موسم الأمطار — نوثق التصاريح بمحضر لتجنب مطالبات.»","result":"55 ثانية."},"example_medium":{"title":"ملخص تنفيذي من صفحة","situation":"إعادة تصميم لوحة المؤشرات.","application":"العنوان يحمل التوصية: «تقليص اللوحة إلى 12 مؤشرًا مرتبطًا بقرارات نائب الأمين». ثلاثة عناوين فرعية = الأسباب الثلاثة، كل منها بجملة ورقم ورسم واحد. الصندوق الأخير: المخاطر والخطوات بأسماء ومواعيد.","result":"قُرئت في 3 دقائق واعتُمدت في الاجتماع نفسه."},"example_advanced":{"title":"الدفاع أمام لجنة منقسمة","situation":"قرار استمرار/إيقاف مشروع بعد إنفاق 58%.","application":"الاعتراض: «الإيقاف يهدر ربع مليار». الرد: «صحيح أن 244 مليونًا أُنفقت، وهي لا تعود في أي خيار؛ السؤال هو أين تذهب الـ215 التالية: النطاق المقلّص يعيد 110 مقابل 95 للاستكمال، وعند تراجع الطلب 25% يعيد 50 مقابل 17.5. ما يغيّر رأيي: تقدير منافع يتجاوز 350 بعد تحديث دراسة الطلب.»","result":"الاعتراف بالوجاهة + رقم حاسم + شرط تغيير الرأي."},"common_mistakes":["سرد التحليل زمنيًا («أولًا جمعنا البيانات…») بدل الجواب أولًا.","أسباب متداخلة أو أكثر من 3-4.","أرقام بلا «ماذا في ذلك».","الدفاع عن كل نقطة والانفعال عند الاعتراض.","تجاوز 90 ثانية بتفاصيل المنهجية."],"checklist":["هل الجملة الأولى هي التوصية برقم؟","هل الأسباب 3 ومستقلة ومرتبة؟","هل لكل رقم «ماذا في ذلك»؟","هل ذكرت المفاضلة والخطر الأهم؟","هل الخطوة التالية بمالك وموعد؟","هل الزمن ≤ 90 ثانية؟"],"exercise":{"prompt":"خذ تحليلًا سبق أن كتبته (أي حالة) وأعد كتابته في 120 كلمة كحد أقصى وفق الهرم، ثم اقرأه بصوت عالٍ وسجّل الزمن. أعد الحذف حتى تبلغ 90 ثانية.","guidance":["احذف كل جملة تبدأ بـ«قمنا بـ» أو «لاحظنا».","استبدل الصفات بالأرقام.","الخطوة التالية جملة واحدة باسم ومهلة."]},"applied_case":{"title":"دقيقة أمام نائب الأمين","scenario":"لديك 60 ثانية لتقديم توصية بشأن إعادة ترتيب محفظة طرق تحت تخفيض 22%. نتائج تحليلك: يلزم توفير 180.4 مليونًا؛ تأجيل الطريق السياحي (110) وإيقاف طريق الخدمة (صافي 81) يوفران 191؛ الهدفان يتحققان (سلامة 20% مقابل 15%، وصول 87% مقابل 85%)؛ الخطر: التزام علني بالطريق السياحي.","data":[{"label":"الحد الزمني","value":"60 ثانية (≈ 110-130 كلمة)"},{"label":"الجمهور","value":"نائب الأمين — يريد القرار والثمن"}],"task":"اكتب نص الدقيقة الواحدة وفق الهرم مع رد جاهز على اعتراض «لا يمكن تأجيل الطريق السياحي».","model_answer":"«لاستيعاب تخفيض 180 مليونًا مع تحقيق هدفي السلامة والوصول، نوصي بتأجيل الطريق السياحي وإيقاف طريق الخدمة الصناعي، وهو ما يوفر 191 مليونًا. أولًا: هذان المشروعان أثرهما على الهدفين شبه معدوم، بينما تحسين التقاطعات الخطرة يمنح أعلى أثر سلامة لكل مليون. ثانيًا: بعد القرار تتحقق السلامة بـ20% مقابل هدف 15%، والوصول 87% مقابل 85%. ثالثًا: تكلفة الخروج من طريق الخدمة 9 ملايين فقط، ولا نحتسب المنصرف لأنه لا يعود. الخطر الأهم: الالتزام العلني بالطريق السياحي — نقترح إعلان إعادة الجدولة للسنة القادمة مع تاريخ محدد. الخطوة التالية: اعتماد الترتيب في لجنة المحفظة خلال أسبوعين.» رد الاعتراض: «الالتزام العلني وجيه؛ البديل الوحيد لإبقائه هو تأجيل محور المستشفى، وهو ما يخفض الوصول إلى 82% دون الهدف. إن وُجد اعتماد إضافي 110 ملايين نعيد الطريق السياحي فورًا»."},"result_interpretation":[{"range":"85-100","meaning":"توصياتك تبدأ بالجواب وتُقدَّم في الزمن وتصمد أمام الاعتراض.","advice":"انتقل إلى محاكاة Case Interview."},{"range":"70-84","meaning":"البنية جيدة لكن الزمن طويل أو الأسباب متداخلة.","advice":"تدرب على الحذف حتى 90 ثانية يوميًا."},{"range":"أقل من 70","meaning":"التوصية مدفونة أو غائبة.","advice":"أعد كتابة آخر 3 إجابات وفق الهرم."}],"next_recommendation":"وحدة «محاكاة Case Interview».","completion_rule":{"quiz_min_score":70,"applied_case_min_score":65,"description":"70% في الاختبار و65% في الحالة التطبيقية."},"primary_skill":"communication"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001110', '00000000-0000-4000-8000-000000000010', 'الدرس الأساسي: Pyramid Principle والتواصل التنفيذي', '{"explanation":["Pyramid Principle (باربرا مينتو): ابدأ بالجواب، ثم اجمع الأسباب في مجموعات منطقية (MECE)، ثم رتبها (بالأهمية، الزمن، أو البنية)، وادعم كل سبب بدليل. القائد يقرأ من الأعلى ويتوقف عندما يقتنع؛ إن دفنت التوصية في الصفحة الخامسة فلن تُقرأ.","بنية الدقيقة الواحدة: (1) الموقف والتعقيد في جملة («تخفيض 22% يهدد هدفي السلامة والوصول»)، (2) التوصية في جملة برقم («نؤجل م6 ونوقف م3 لتوفير 191 مليونًا مع تحقيق الهدفين»)، (3) ثلاثة أسباب مرقّمة بأرقام، (4) المخاطر والخطوة التالية. 90 ثانية تكفي لهذا كله إذا حذفت كل ما لا يخدم القرار.","قاعدة «ماذا في ذلك؟» (So what?): كل رقم يجب أن يتبعه معناه للقرار. «أثر م5 0.1% لكل مليون» → «أي 3 أضعاف أي مشروع آخر، لذا يبدأ فورًا». وقاعدة «كيف تعرف؟»: كل ادعاء يتبعه دليله. الجملة التي لا تجيب عن أحد السؤالين تُحذف.","الاعتراضات: القادة يختبرون التوصية بأسئلة ضاغطة («لماذا لا نقبل عرض المستثمر؟»). الجواب الجيد: اعترف بالوجاهة، أعطِ الرقم الحاسم، أعد الربط بالتوصية. لا تدافع عن كل نقطة؛ سمّ ما يغيّر رأيك («إن رفع المستثمر الحد المضمون إلى 20 مليونًا سنويًا أعدنا الحساب»). هذا يظهر أن التوصية مبنية على منطق لا على موقف."],"terms":[{"ar":"مبدأ الهرم","en":"Pyramid Principle","definition":"الجواب أولًا ثم الأسباب المجمّعة ثم الأدلة."},{"ar":"الموقف-التعقيد-السؤال-الجواب","en":"SCQA","definition":"افتتاحية تضع السياق قبل التوصية في جملتين."},{"ar":"ماذا في ذلك؟","en":"So What?","definition":"اختبار أن كل رقم يتبعه معناه للقرار."},{"ar":"التجميع المنطقي","en":"Logical Grouping","definition":"ضم الأسباب في مجموعات MECE مرتبة."},{"ar":"الملخص التنفيذي","en":"Executive Summary","definition":"صفحة واحدة تحمل التوصية والأسباب والخطوة التالية."}],"method_steps":["اكتب التوصية في جملة واحدة برقم حاسم.","اكتب كل الأسباب ثم اجمعها في 3 مجموعات MECE.","رتب المجموعات بالأهمية لصاحب القرار.","لكل سبب: دليل رقمي واحد + «ماذا في ذلك».","أضف المفاضلة والمخاطر في جملتين.","اختم بالخطوة التالية ومن يملكها ومتى.","اقرأها بصوت عالٍ وقِس الزمن: احذف حتى تبلغ 90 ثانية."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000100001', '00000000-0000-4000-8000-000000000010', 'communication', 'expert', 'ordering', 'رتب عناصر التقديم التنفيذي وفق الهرم.', '[{"id":"e1","text":"ثلاثة أسباب مرقّمة بأرقام"},{"id":"e2","text":"التوصية في جملة برقم"},{"id":"e3","text":"الموقف والتعقيد في جملة"},{"id":"e4","text":"المخاطر والمفاضلة"},{"id":"e5","text":"الخطوة التالية بمالك وموعد"}]'::jsonb, '{"order":["e3","e2","e1","e4","e5"]}'::jsonb, 'SCQ ← الجواب ← الأسباب ← المخاطر ← الخطوة التالية.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000100002', '00000000-0000-4000-8000-000000000010', 'communication', 'expert', 'compare_recommendations', 'قارن: (1) «قمنا بتحليل 6 مشاريع وجمعنا البيانات ووجدنا أن بعضها أهم من بعض، وفي النهاية نرى أنه من الأفضل ربما تأجيل بعض المشاريع». (2) «نوصي بتأجيل م6 وإيقاف م3 لتوفير 191 مليونًا مع تحقيق الهدفين: (1) أثرهما صفر، (2) السلامة تصبح 20%، (3) تكلفة الخروج 9 ملايين». ما الفروق الثلاثة الجوهرية؟', '[]'::jsonb, '{"keywords":["الجواب","أرقام","سرد","أسباب"],"min_matches":2}'::jsonb, 'الثانية تبدأ بالجواب، مدعومة بأرقام، بأسباب مرقّمة؛ الأولى سرد زمني بلا توصية ولا أرقام.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000100003', '00000000-0000-4000-8000-000000000010', 'communication', 'expert', 'true_false', 'عند اعتراض القائد على توصيتك، الأفضل الدفاع عن كل نقطة بالتفصيل لإثبات عمق التحليل.', '[]'::jsonb, '{"value":false}'::jsonb, 'اعترف بالوجاهة، أعطِ الرقم الحاسم، وسمّ ما يغيّر رأيك؛ الدفاع عن كل نقطة يفقد البنية.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000100004', '00000000-0000-4000-8000-000000000010', 'communication', 'expert', 'spot_error', '«أثر مشروع التقاطعات 0.1% لكل مليون.» ما الذي ينقص هذه الجملة في تقديم تنفيذي؟', '[{"id":"a","text":"المصدر"},{"id":"b","text":"«ماذا في ذلك»: معنى الرقم للقرار (3 أضعاف أي مشروع آخر، لذا يبدأ فورًا)"},{"id":"c","text":"لا ينقصها شيء"},{"id":"d","text":"يجب تحويلها إلى نسبة مئوية"}]'::jsonb, '{"option":"b"}'::jsonb, 'الرقم بلا معناه للقرار يترك القائد يحسب بنفسه.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000100005', '00000000-0000-4000-8000-000000000010', 'communication', 'expert', 'numeric', 'نص تقديمك 260 كلمة ومعدل قراءتك التنفيذية 130 كلمة/دقيقة. كم كلمة يجب حذفها لتبلغ 90 ثانية؟', '[]'::jsonb, '{"value":65,"tolerance":1}'::jsonb, '90 ثانية = 1.5 دقيقة × 130 = 195 كلمة؛ 260 − 195 = 65.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000100006', '00000000-0000-4000-8000-000000000010', 'communication', 'expert', 'written_recommendation', 'اكتب توصية تنفيذية من 80-120 كلمة تبدأ بالجواب، لقرار تقليص لوحة مؤشرات من 64 إلى 12 مؤشرًا (البيانات: 64% تشغيلية، 53% ثابتة أو بلا مالك، نائب الأمين استخدم 9 مؤشرات فقط).', '[]'::jsonb, '{"keywords":["نوصي","12","64%","قرار","مالك"],"min_matches":3}'::jsonb, 'التوصية أولًا ثم ثلاثة أسباب رقمية ثم الخطوة التالية.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000011', 'case-interview-simulation', 'محاكاة Case Interview', 'إدارة حوار الحالة في نمطي Interviewer-Led وCandidate-Led، وطلب البيانات، والتعامل مع ضغط الوقت، ومقابلة الخبرة الشخصية.', 'expert', 11, '{"learning_objective":"تدير حالة كاملة خلال 25-35 دقيقة بإيقاع احترافي: إعادة الصياغة، الهيكل، الفرضية، طلب البيانات، الحساب بصوت مسموع، التركيب، والتوصية النهائية؛ وتقدم قصة خبرة شخصية بصيغة STAR-R في 3 دقائق.","explanation":["نمط Interviewer-Led (أسلوب ماكنزي): المحاور يقود بأسئلة متتابعة (هيكل، حساب، رسم، توصية)؛ نجاحك في جودة كل إجابة والانتقال السلس. نمط Candidate-Led (أسلوب BCG/Bain): أنت تقود من البداية إلى التوصية، وتطلب البيانات، وتقرر أين تتعمق. في كلا النمطين تُقاس: الهيكلة، الحساب، الحكم التجاري، والتواصل.","الإيقاع القياسي: (1) 1-2 دقيقة إعادة صياغة وأسئلة توضيحية (الهدف، القيود، الزمن)؛ (2) 2-3 دقائق بناء الهيكل وعرضه؛ (3) 10-15 دقيقة تحليل: فرضية → طلب بيان → حساب → «ماذا في ذلك»؛ (4) 2-3 دقائق تركيب وتوصية. طلب البيانات يكون محددًا ومبررًا: «أطلب توزيع الأعطال بعمر العمود لاختبار فرضية التقادم».","تحت ضغط الوقت (تحدي 60-90 ثانية): استخدم الهرم مباشرة؛ لا تفكر بصوت عالٍ في كل شيء، بل قل: «سأفترض كذا، وإن كان مخالفًا أُعدل». الصمت 5 ثوانٍ لترتيب الفكرة أفضل من 30 ثانية حشو.","مقابلة الخبرة الشخصية (PEI): قصة واحدة عميقة لا ثلاث سطحية. الصيغة STAR-R: الموقف، المهمة، الفعل (ما فعلته أنت تحديدًا، لا الفريق)، النتيجة برقم، والتأمل (ماذا تعلمت وماذا ستفعل مختلفًا). المحاور يبحث عن: القيادة، الأثر الشخصي، التعامل مع الخلاف، والنزاهة."],"terms":[{"ar":"الحالة بقيادة المحاور","en":"Interviewer-Led Case","definition":"المحاور يوجه بأسئلة متتابعة."},{"ar":"الحالة بقيادة المرشح","en":"Candidate-Led Case","definition":"المرشح يقود من الهيكل إلى التوصية."},{"ar":"إعادة الصياغة","en":"Recap / Clarification","definition":"تلخيص الحالة وسؤال القرار قبل التحليل."},{"ar":"التركيب","en":"Synthesis","definition":"جمع النتائج في توصية واحدة مع الأسباب."},{"ar":"مقابلة الخبرة الشخصية","en":"Personal Experience Interview (PEI)","definition":"مقابلة سلوكية عن موقف حقيقي بصيغة STAR-R."}],"method_steps":["أعد صياغة الحالة وسؤال القرار واسأل عن الهدف والقيود والزمن.","اطلب دقيقة لبناء الهيكل، ثم اعرضه بثلاثة فروع مع الفرع الذي تبدأ به.","اذكر فرضيتك واطلب بيانًا محددًا مبررًا.","احسب بصوت مسموع مع تقريب معلن، ثم «ماذا في ذلك».","عند بيان مخالف: عدّل الفرضية صراحة.","قبل النهاية بدقيقتين: ركّب التوصية بالهرم.","في PEI: قصة واحدة STAR-R مع فعلك الشخصي ورقم نتيجة."],"example_simple":{"title":"افتتاحية حالة","situation":"المحاور: «بلدية تريد خفض زمن الرخص من 31 إلى 12 يومًا».","application":"«للتأكد: الهدف 12 يومًا للرخص السكنية؟ خلال أي مدة؟ وهل الميزانية وعدد الموظفين ثابتان؟ سأبني هيكلي على مراحل المسار: التقديم، المراجعة الفنية، الاعتماد، الإصدار، وأبدأ بالمرحلة التي تستهلك معظم الزمن الإضافي — فرضيتي المراجعة الفنية. أطلب زمن كل مرحلة الآن مقارنة بعام سابق.»","result":"دقيقتان: صياغة + هيكل + فرضية + طلب بيان."},"example_medium":{"title":"تعديل الفرضية أمام بيان مخالف","situation":"طلبت سجل المعدات لإثبات نقصها، فجاء السجل مطابقًا للمخطط.","application":"«هذا ينفي فرضية المعدات. أنتقل إلى الفرضية الثانية: إنتاجية المعدات (ساعات التشغيل الفعلية). أطلب ساعات التشغيل اليومية للحفارات.» — بلا تبرير مطول.","result":"المحاور يقيّم مرونة التفكير لا صحة الفرضية الأولى."},"example_advanced":{"title":"الدفاع في الدور الأخير","situation":"المحاور يلعب دور نائب الأمين ويرفض التوصية.","application":"«أتفهم أن الالتزام العلني قيد حقيقي. البديل الوحيد لإبقاء الطريق السياحي هو تأجيل محور المستشفى، ما يخفض الوصول إلى 82% دون الهدف. أوصي بإعلان إعادة الجدولة بتاريخ محدد، وإن ظهر اعتماد إضافي 110 ملايين نعيده فورًا.»","result":"الثبات على المنطق مع تقديم مخرج."},"common_mistakes":["البدء بالتحليل قبل إعادة الصياغة والأسئلة التوضيحية.","هيكل من قالب محفوظ لا يخص الحالة.","طلب بيانات عامة («هل لديكم بيانات أخرى؟»).","الحساب في صمت ثم إعلان رقم خاطئ.","توصية في آخر 10 ثوانٍ بلا تركيب.","قصة PEI عن الفريق لا عن فعلك الشخصي."],"checklist":["هل أعدت الصياغة وسألت عن الهدف والقيود؟","هل عرضت هيكلًا مخصصًا وحددت نقطة البداية؟","هل كل طلب بيان مبرر بفرضية؟","هل حسبت بصوت مسموع وأتبعت الرقم بمعناه؟","هل ركّبت التوصية قبل انتهاء الوقت؟","هل قصة PEI بصيغة STAR-R برقم؟"],"exercise":{"prompt":"سجّل نفسك (أو اكتب) خلال 3 دقائق: افتتاحية حالة «ارتفاع أوامر التغيير إلى 13%» تتضمن إعادة الصياغة، سؤالين توضيحيين، هيكلًا من 3 فروع، فرضية، وطلب بيان واحد مبرر.","guidance":["الأسئلة التوضيحية عن الهدف والقيود، لا عن الحلول.","الفروع من الحالة: مصدر التغيير، حوكمة الاعتماد، التسعير.","طلب البيان: «توزيع قيمة الأوامر بالمصدر لاختبار فرضية طلبات الجهة»."]},"applied_case":{"title":"حالة بقيادة المرشح: تعثر المقاول أم النطاق؟","scenario":"محاور يقدم: «وكيل الوكالة يريد معرفة لماذا تعثر 12 من 30 مشروعًا لمقاول واحد، وهل يُستبعد من المنافسات القادمة». لديك 20 دقيقة. البيانات تُعطى عند الطلب فقط.","data":[{"label":"عند الطلب: نسبة تعثر المقاولين الآخرين","value":"38% (مقابل 40% لهذا المقاول)"},{"label":"عند الطلب: توزيع أسباب تعثر مشاريع المقاول","value":"تغيير نطاق 50%، نقل خدمات 25%، أداء 25%"},{"label":"عند الطلب: تقييم الأداء الفني للمقاول","value":"4.1 من 5 (أعلى من المتوسط 3.6)"},{"label":"عند الطلب: حصة المقاول من المحفظة","value":"30 من 85 مشروعًا (35%)"}],"task":"اكتب سيناريو إدارتك للحالة: الصياغة، الهيكل، الفرضيات، البيانات التي تطلبها بالترتيب، الحساب، والتوصية النهائية للوكيل.","model_answer":"الصياغة: «سؤال القرار: هل تعثر 40% من مشاريع المقاول ناتج عن أدائه بحيث يبرر استبعاده، أم عن عوامل في المحفظة؟ القيد: الحفاظ على قدرة التنفيذ (35% من المحفظة).» الهيكل: (أ) أداء المقاول نسبيًا، (ب) أسباب التعثر بالمصدر، (ج) أثر الاستبعاد على القدرة. الفرضية: التعثر محفظي لا خاص بالمقاول. البيانات بالترتيب: (1) تعثر الآخرين — 38% ≈ 40%، فالمقاول ليس شاذًا؛ (2) الأسباب — 75% نطاق ونقل خدمات مملوكة للجهة؛ (3) التقييم الفني 4.1 > 3.6. الحساب: التعثر المنسوب لأداء المقاول = 25% × 12 = 3 مشاريع من 30 = 10%، أقل من متوسط المحفظة. التركيب: «لا نوصي باستبعاد المقاول؛ تعثره يماثل المحفظة وسببه في 75% منه حوكمة الجهة (نطاق ونقل خدمات). نوصي بدلًا من ذلك: بوابة تجميد تصميم ومسار مبكر لنقل الخدمات، مع سقف 25% لأي مقاول مستقبلًا لتقليل مخاطر التركّز. المخاطر: تركّز 35% في مقاول واحد يبقى خطرًا محفظيًا.» عند اعتراض الوكيل («لكن الناس يرون المقاول سببًا»): «الأرقام تقول إن استبعاده يعالج 10% من التعثر ويفقدنا 35% من القدرة»."},"result_interpretation":[{"range":"85-100","meaning":"تدير الحالة بإيقاع احترافي وتركّب التوصية في الوقت.","advice":"انتقل إلى الحالات المتكاملة للخبير المتقدم."},{"range":"70-84","meaning":"المحتوى جيد لكن الإيقاع أو طلب البيانات يحتاج ضبطًا.","advice":"تدرب على 3 حالات Interviewer-Led بمؤقت."},{"range":"أقل من 70","meaning":"تبدأ بالتحليل قبل الصياغة أو تفقد التوصية.","advice":"راجع الإيقاع القياسي وأعد التمرين بمؤقت."}],"next_recommendation":"وحدة «الحالات المتكاملة للخبير المتقدم».","completion_rule":{"quiz_min_score":70,"applied_case_min_score":65,"description":"70% في الاختبار و65% في الحالة التطبيقية."},"primary_skill":"case_interview"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001111', '00000000-0000-4000-8000-000000000011', 'الدرس الأساسي: محاكاة Case Interview', '{"explanation":["نمط Interviewer-Led (أسلوب ماكنزي): المحاور يقود بأسئلة متتابعة (هيكل، حساب، رسم، توصية)؛ نجاحك في جودة كل إجابة والانتقال السلس. نمط Candidate-Led (أسلوب BCG/Bain): أنت تقود من البداية إلى التوصية، وتطلب البيانات، وتقرر أين تتعمق. في كلا النمطين تُقاس: الهيكلة، الحساب، الحكم التجاري، والتواصل.","الإيقاع القياسي: (1) 1-2 دقيقة إعادة صياغة وأسئلة توضيحية (الهدف، القيود، الزمن)؛ (2) 2-3 دقائق بناء الهيكل وعرضه؛ (3) 10-15 دقيقة تحليل: فرضية → طلب بيان → حساب → «ماذا في ذلك»؛ (4) 2-3 دقائق تركيب وتوصية. طلب البيانات يكون محددًا ومبررًا: «أطلب توزيع الأعطال بعمر العمود لاختبار فرضية التقادم».","تحت ضغط الوقت (تحدي 60-90 ثانية): استخدم الهرم مباشرة؛ لا تفكر بصوت عالٍ في كل شيء، بل قل: «سأفترض كذا، وإن كان مخالفًا أُعدل». الصمت 5 ثوانٍ لترتيب الفكرة أفضل من 30 ثانية حشو.","مقابلة الخبرة الشخصية (PEI): قصة واحدة عميقة لا ثلاث سطحية. الصيغة STAR-R: الموقف، المهمة، الفعل (ما فعلته أنت تحديدًا، لا الفريق)، النتيجة برقم، والتأمل (ماذا تعلمت وماذا ستفعل مختلفًا). المحاور يبحث عن: القيادة، الأثر الشخصي، التعامل مع الخلاف، والنزاهة."],"terms":[{"ar":"الحالة بقيادة المحاور","en":"Interviewer-Led Case","definition":"المحاور يوجه بأسئلة متتابعة."},{"ar":"الحالة بقيادة المرشح","en":"Candidate-Led Case","definition":"المرشح يقود من الهيكل إلى التوصية."},{"ar":"إعادة الصياغة","en":"Recap / Clarification","definition":"تلخيص الحالة وسؤال القرار قبل التحليل."},{"ar":"التركيب","en":"Synthesis","definition":"جمع النتائج في توصية واحدة مع الأسباب."},{"ar":"مقابلة الخبرة الشخصية","en":"Personal Experience Interview (PEI)","definition":"مقابلة سلوكية عن موقف حقيقي بصيغة STAR-R."}],"method_steps":["أعد صياغة الحالة وسؤال القرار واسأل عن الهدف والقيود والزمن.","اطلب دقيقة لبناء الهيكل، ثم اعرضه بثلاثة فروع مع الفرع الذي تبدأ به.","اذكر فرضيتك واطلب بيانًا محددًا مبررًا.","احسب بصوت مسموع مع تقريب معلن، ثم «ماذا في ذلك».","عند بيان مخالف: عدّل الفرضية صراحة.","قبل النهاية بدقيقتين: ركّب التوصية بالهرم.","في PEI: قصة واحدة STAR-R مع فعلك الشخصي ورقم نتيجة."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000110001', '00000000-0000-4000-8000-000000000011', 'case_interview', 'expert', 'ordering', 'رتب مراحل الحالة بقيادة المرشح.', '[{"id":"p1","text":"تحليل: فرضية ← بيان ← حساب"},{"id":"p2","text":"إعادة الصياغة والأسئلة التوضيحية"},{"id":"p3","text":"التركيب والتوصية"},{"id":"p4","text":"بناء الهيكل وعرضه"}]'::jsonb, '{"order":["p2","p4","p1","p3"]}'::jsonb, 'صياغة ← هيكل ← تحليل ← تركيب.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000110002', '00000000-0000-4000-8000-000000000011', 'case_interview', 'expert', 'mcq', 'أي طلب بيانات هو الأفضل في حالة تعثر مقاول؟', '[{"id":"a","text":"هل لديكم بيانات أخرى عن المقاول؟"},{"id":"b","text":"أطلب نسبة تعثر المقاولين الآخرين لاختبار فرضية أن التعثر محفظي لا خاص بهذا المقاول."},{"id":"c","text":"أريد كل تقارير المشاريع."},{"id":"d","text":"ما رأيكم في المقاول؟"}]'::jsonb, '{"option":"b"}'::jsonb, 'طلب محدد ومبرر بفرضية.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000110003', '00000000-0000-4000-8000-000000000011', 'case_interview', 'expert', 'true_false', 'في نمط Interviewer-Led يجب أن تفرض هيكلك الكامل قبل الإجابة عن سؤال المحاور الأول.', '[]'::jsonb, '{"value":false}'::jsonb, 'المحاور يقود؛ تجيب عن سؤاله بهيكل موجز ثم تتبع تسلسله.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000110004', '00000000-0000-4000-8000-000000000011', 'case_interview', 'expert', 'numeric', '12 مشروعًا متعثرًا من 30 لمقاول؛ 25% من التعثر منسوب لأدائه. ما نسبة مشاريعه المتعثرة بسبب أدائه من إجمالي مشاريعه (%)؟', '[]'::jsonb, '{"value":10,"tolerance":0.5}'::jsonb, '0.25 × 12 = 3؛ 3 ÷ 30 = 10%.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000110005', '00000000-0000-4000-8000-000000000011', 'case_interview', 'expert', 'spot_error', 'قصة PEI: «واجه فريقنا مقاومة من الإدارات، فعقدنا ورشًا وأقنعناهم، ونجح المشروع.» ما الخطأ؟', '[{"id":"a","text":"القصة قصيرة"},{"id":"b","text":"لا فعل شخصي محدد، لا نتيجة رقمية، لا تأمل — تتحدث عن الفريق لا عنك"},{"id":"c","text":"يجب ذكر أسماء الإدارات"},{"id":"d","text":"لا خطأ"}]'::jsonb, '{"option":"b"}'::jsonb, 'STAR-R يتطلب فعلك أنت، ورقمًا للنتيجة، وتأملًا.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;
insert into academy.question_bank (id, module_id, skill, level, question_type, question, options, correct_answer, explanation, is_published) values ('00000000-0000-4000-8000-000000110006', '00000000-0000-4000-8000-000000000011', 'case_interview', 'expert', 'short_answer', 'اكتب افتتاحية (3-4 جمل) لحالة «خفض زمن الرخص من 31 إلى 12 يومًا» تتضمن إعادة الصياغة وسؤالين توضيحيين والفرع الذي ستبدأ به.', '[]'::jsonb, '{"keywords":["الهدف","القيود","مرحلة","أبدأ","فرضية"],"min_matches":3}'::jsonb, 'صياغة + سؤالان (هدف/قيود) + هيكل بمراحل + نقطة بداية مبررة.', true)
  on conflict (id) do update set skill = excluded.skill, level = excluded.level, question_type = excluded.question_type, question = excluded.question, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation;

insert into academy.modules (id, slug, title, description, level, order_index, content, is_published) values ('00000000-0000-4000-8000-000000000012', 'integrated-advanced-cases', 'الحالات المتكاملة للخبير المتقدم', 'حالات غامضة متعددة المراحل بأهداف متعارضة وبيانات ناقصة، واكتشاف الانحيازات والافتراضات غير المعلنة، والدفاع عن التوصية أمام لجنة قيادية.', 'advanced_expert', 12, '{"learning_objective":"تدير حالة متعددة المراحل من التشخيص إلى خطة 100 يوم ومؤشرات المتابعة، وتكتشف الانحيازات (التكلفة الغارقة، التأكيد، الإرساء) والافتراضات غير المعلنة في بيانات الحالة، وتقدم توصية لنائب الأمين وتدافع عنها تحت ضغط الأسئلة دون فقدان البنية.","explanation":["في الحالات المتقدمة تكون البيانات ناقصة أو متعارضة عمدًا. المهارة ليست انتظار البيانات الكاملة بل: تسمية الافتراض صراحة، تقدير أثره على القرار، وتحديد بوابة تحقق لاحقة. «سأفترض أن تقدير المنافع صحيح ±25%؛ إن كان أسوأ من ذلك ينقلب القرار، لذا نضع بوابة تحديث خلال أسبوعين».","الأهداف المتعارضة (السلامة مقابل الرضا، الالتزام العلني مقابل القيمة) لا تُحل بالتوفيق بل بالترتيب الصريح مستندًا إلى أولويات صاحب القرار، مع تعويض جزئي للهدف المؤجل. المستشار المتقدم يجعل الثمن مرئيًا ويقدم مخرجًا لأصحاب المصلحة المتضررين.","الانحيازات الشائعة في حالات القطاع العام: التكلفة الغارقة («أنفقنا الكثير»)، التأكيد («نحن نعرف أن المقاول هو السبب»)، الإرساء على الرقم الأول («التقدير 480 مليونًا»)، والتفاؤل في الجداول. مهمتك تسميتها بأدب وبالأرقام: «الرقم 480 من دراسة قبل تغيير الطريق؛ التقدير المحدث 310».","خطة 100 يوم تحوّل التوصية إلى تنفيذ: ثلاث موجات (استقرار، بناء الآليات، مراجعة المحفظة)، لكل بند مالك وموعد ومؤشر وعتبة تصعيد. لوحة المتابعة ≤ 8 مؤشرات، ومراجعة أسبوعية للتصعيد. الدفاع أمام اللجنة: توقع الأسئلة الخمسة الأصعب وجهّز لكل منها رقمًا حاسمًا وشرطًا يغيّر رأيك."],"terms":[{"ar":"الافتراض غير المعلن","en":"Unstated Assumption","definition":"افتراض يعتمد عليه التحليل دون التصريح به."},{"ar":"انحياز الإرساء","en":"Anchoring Bias","definition":"التعلق بأول رقم يُطرح."},{"ar":"خطة 100 يوم","en":"100-Day Plan","definition":"خطة تنفيذ بثلاث موجات بمالك ومؤشر لكل بند."},{"ar":"بوابة التحقق","en":"Validation Gate","definition":"نقطة لاحقة يُراجع فيها الافتراض قبل الالتزام النهائي."},{"ar":"الدفاع عن التوصية","en":"Recommendation Defense","definition":"الرد على اعتراضات القيادة بالأرقام مع تسمية ما يغيّر الرأي."}],"method_steps":["اقرأ الحالة مرتين: الأولى للمشكلة، الثانية لصيد الافتراضات والتناقضات.","اكتب قائمة «ما لا أعرفه» وقدّر أثر كل مجهول على القرار.","رتب الأهداف المتعارضة صراحة وفق أولويات صاحب القرار.","حلل الخيارات (بما فيها المقلّص والمؤجل) بالسيناريوهات.","سمّ الانحيازات في البيانات أو في مواقف أصحاب المصلحة بالأرقام.","اكتب التوصية بالهرم مع بوابات تحقق للافتراضات الحاكمة.","ابنِ خطة 100 يوم بثلاث موجات ولوحة ≤ 8 مؤشرات.","جهّز الأسئلة الخمسة الأصعب وأجوبتها الرقمية."],"example_simple":{"title":"افتراض غير معلن في تقدير المنافع","situation":"منافع مشروع 480 مليونًا من دراسة قبل 3 سنوات.","application":"الافتراض غير المعلن: الطلب لم يتغير. الواقع: تغيّر مسار الطريق وانخفضت الزيارات 35%. الأثر: المنافع 310. القرار ينقلب من الاستكمال إلى النطاق المقلّص.","result":"تسمية الافتراض غيّرت القرار قبل أي تحليل إضافي."},"example_medium":{"title":"دمج وحدتين تنظيميتين","situation":"دمج إدارة الحدائق وإدارة الإنارة لتوفير 15%.","application":"الافتراضات غير المعلنة: أن التوفير من الإدارة لا من التشغيل، وأن الكفاءات قابلة للتبادل. البيانات: 82% من الميزانيتين عقود تشغيل لا تتأثر بالدمج؛ التوفير الحقيقي من الإدارة ≈ 4%. الهدف المتعارض: توفير 15% مقابل استمرارية الخدمة. التوصية: دمج الإدارة المساندة (4%) + إعادة طرح عقود التشغيل موحدة (8-10% بعد 12 شهرًا).","result":"هدف 15% أُعيد تعريفه زمنيًا بدل الوعد بما لا يتحقق."},"example_advanced":{"title":"خطة 100 يوم لمحفظة متعثرة أمام لجنة","situation":"40% تعثر، لجنة منقسمة بين معاقبة المقاولين وإعادة الحوكمة.","application":"الموجة 1 (1-30): ميثاق، ملاك قرارات، لجنة تصعيد. الموجة 2 (31-60): بوابات، SLA للجهات الخدمية، سجل مخاطر محفظي. الموجة 3 (61-100): بوابة استمرار/تقليص/إيقاف لـ34 مشروعًا. المؤشرات: زمن التصعيد، تغييرات النطاق بعد التنفيذ، نسبة المشاريع الملتزمة. الأسئلة الخمسة: «لماذا لا نستبعد المقاول؟» (10% فقط من التعثر)، «كم يكلف؟» (بلا زيادة موظفين)، «متى نرى الأثر؟» (زمن التصعيد خلال 30 يومًا)، «ماذا لو قاومت الإدارات؟» (ميثاق موقّع من الرئيس)، «ما الذي يغيّر رأيك؟» (إن تجاوز تعثر المقاول المتوسط بـ15 نقطة).","result":"اعتُمدت الخطة مع تفويض واضح."},"common_mistakes":["انتظار بيانات كاملة بدل تسمية الافتراض وبوابة التحقق.","التوفيق بين الأهداف المتعارضة بدل ترتيبها.","تجاهل الانحيازات المزروعة في الحالة.","خطة تنفيذ بلا ملاك أو مؤشرات أو موجات.","الانهيار عند الاعتراض أو التراجع عن التوصية بلا رقم جديد."],"checklist":["هل كتبت قائمة المجهولات وأثرها؟","هل رتبت الأهداف المتعارضة صراحة؟","هل سميت الانحيازات بالأرقام؟","هل للافتراضات الحاكمة بوابات تحقق؟","هل خطة 100 يوم بثلاث موجات وملاك ومؤشرات؟","هل جهزت الأسئلة الخمسة الأصعب؟"],"exercise":{"prompt":"اختر حالة سابقة حصلت فيها على أقل من 70. اكتب: (1) ثلاثة افتراضات غير معلنة كانت في الحالة، (2) الانحياز الذي وقعت فيه، (3) خطة 100 يوم من 6 بنود بمالك ومؤشر، (4) الأسئلة الثلاثة الأصعب من نائب الأمين وأجوبتها الرقمية.","guidance":["الافتراض غير المعلن غالبًا في «التقديرات» و«الالتزامات».","المؤشر رقم وعتبة وزمن.","كل جواب على اعتراض يحتوي رقمًا حاسمًا وشرطًا يغيّر رأيك."]},"applied_case":{"title":"إعادة هيكلة وكالة خدمات بلدية تحت أهداف متعارضة","scenario":"وكالة خدمات بلدية (1,400 موظف، 5 إدارات) مطلوب منها: خفض التكاليف التشغيلية 12%، ورفع رضا المستفيدين من 61% إلى 72%، ورقمنة 80% من الخدمات — كلها خلال 18 شهرًا. تحليلك الأولي يظهر تعارضًا: الرقمنة تحتاج استثمارًا 38 مليونًا في السنة الأولى، وخفض التكاليف الفوري يعني تقليص عقود الخدمة الميدانية التي تحرك 70% من الرضا. بيانات كثيرة ناقصة: لا يوجد تقدير لعائد الرقمنة، والرضا مقاس باستبيان منحاز، ووعد علني بالرقمنة أُعلن قبل شهرين.","data":[{"label":"الميزانية التشغيلية","value":"310 مليون (عقود ميدانية 62%، رواتب 28%، أخرى 10%)"},{"label":"استثمار الرقمنة","value":"38 مليون السنة الأولى؛ توفير تشغيلي متوقع بعد 24 شهرًا: 6-9% (غير موثق)"},{"label":"محركات الرضا","value":"الخدمة الميدانية 70%، القنوات الرقمية 15%، أخرى 15%"},{"label":"الاستبيان","value":"410 إجابات من 3 أحياء (30% من السكان)"},{"label":"الالتزام العلني","value":"رقمنة 80% خلال 18 شهرًا"}],"task":"قدّم توصية متكاملة لنائب الأمين: ترتيب الأهداف، الافتراضات غير المعلنة وبوابات تحققها، الانحيازات، خطة 100 يوم، لوحة مؤشرات، والأسئلة الثلاثة الأصعب مع أجوبتها.","model_answer":"التوصية: تحقيق الأهداف الثلاثة على مسارين زمنيين لا واحد — الرضا وخفض التكاليف الإداري (4%) خلال 18 شهرًا، والرقمنة على مرحلتين (50% خلال 18 شهرًا، 80% خلال 30) مع إعادة تعريف هدف التكلفة إلى 12% خلال 30 شهرًا. الترتيب: الرضا أولًا لأنه الهدف الذي يشعر به المستفيد وتحركه العقود الميدانية (70%)؛ قصّها لخفض فوري يدمر الهدف الأول. الافتراضات غير المعلنة: (1) أن الرقمنة توفر تكاليف — لا تقدير موثق؛ بوابة تحقق: دراسة عائد خلال 45 يومًا قبل الالتزام بـ38 مليونًا؛ (2) أن الرضا 61% رقم صحيح — الاستبيان منحاز (3 أحياء)؛ بوابة: مسح ممثل خلال 30 يومًا؛ (3) أن الأهداف متزامنة — الالتزام العلني ذكر الرقمنة فقط، فالتكلفة والرضا قابلان لإعادة الجدولة. الانحيازات: الإرساء على «80% خلال 18 شهرًا» والتفاؤل في عائد الرقمنة. الحساب: خفض 12% = 37 مليونًا؛ من الإداري (10% من 310 = 31 مليون) يمكن توفير 4% من الإجمالي (12 مليونًا) بدمج الإدارات المساندة؛ الباقي (25 مليونًا) من إعادة طرح العقود الميدانية موحدة بعد 12 شهرًا لا من قصّها الآن. خطة 100 يوم: الموجة 1 (1-30): مسح رضا ممثل، دراسة عائد الرقمنة، تعيين ملاك الأهداف الثلاثة؛ الموجة 2 (31-60): دمج الإدارات المساندة، تصميم حزمة العقود الموحدة، إطلاق 5 خدمات رقمية عالية الطلب؛ الموجة 3 (61-100): بوابة قرار الرقمنة (مضي/تقليص) بناءً على الدراسة، خطة الطرح، لوحة المتابعة. اللوحة (6 مؤشرات): الرضا الممثل، زمن حل البلاغ، التكلفة التشغيلية/الخدمة، نسبة الخدمات الرقمية، نسبة المعاملات الرقمية الفعلية، الالتزام بخطة الطرح. الأسئلة الأصعب: (1) «الوعد العلني 80% خلال 18 شهرًا» — الرد: 50% من الخدمات تمثل 85% من المعاملات؛ نحقق الأثر ونعلن المرحلة الثانية بتاريخ؛ (2) «لماذا لا نقص العقود الآن؟» — الرد: كل 10% قص يخفض الرضا ~7 نقاط فيهدر الهدف الأول؛ (3) «ما الذي يغيّر رأيك؟» — الرد: إن أثبتت دراسة العائد توفيرًا ≥ 9% خلال 18 شهرًا نعجّل الرقمنة الكاملة."},"result_interpretation":[{"range":"85-100","meaning":"تدير الغموض والتعارض والانحياز وتحوّل التوصية إلى تنفيذ مدافَع عنه.","advice":"مارس حالات advanced_expert بنمط Interviewer-Led أسبوعيًا."},{"range":"70-84","meaning":"التحليل قوي لكن خطة التنفيذ أو الدفاع يحتاج تعميقًا.","advice":"ركّز على خطة 100 يوم والأسئلة الخمسة."},{"range":"أقل من 70","meaning":"تنتظر البيانات أو توفّق بين الأهداف بدل ترتيبها.","advice":"أعد التمرين مع قائمة المجهولات وبوابات التحقق."}],"next_recommendation":"حالات متكاملة متجددة في محاكاة الحالة بمستوى الخبير المتقدم مع مؤقت.","completion_rule":{"quiz_min_score":75,"applied_case_min_score":70,"description":"75% في الاختبار و70% في الحالة التطبيقية."},"primary_skill":"execution_planning"}'::jsonb, true)
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, level = excluded.level, order_index = excluded.order_index, content = excluded.content, is_published = excluded.is_published;
insert into academy.lessons (id, module_id, title, content, order_index) values ('00000000-0000-4000-8000-000000001112', '00000000-0000-4000-8000-000000000012', 'الدرس الأساسي: الحالات المتكاملة للخبير المتقدم', '{"explanation":["في الحالات المتقدمة تكون البيانات ناقصة أو متعارضة عمدًا. المهارة ليست انتظار البيانات الكاملة بل: تسمية الافتراض صراحة، تقدير أثره على القرار، وتحديد بوابة تحقق لاحقة. «سأفترض أن تقدير المنافع صحيح ±25%؛ إن كان أسوأ من ذلك ينقلب القرار، لذا نضع بوابة تحديث خلال أسبوعين».","الأهداف المتعارضة (السلامة مقابل الرضا، الالتزام العلني مقابل القيمة) لا تُحل بالتوفيق بل بالترتيب الصريح مستندًا إلى أولويات صاحب القرار، مع تعويض جزئي للهدف المؤجل. المستشار المتقدم يجعل الثمن مرئيًا ويقدم مخرجًا لأصحاب المصلحة المتضررين.","الانحيازات الشائعة في حالات القطاع العام: التكلفة الغارقة («أنفقنا الكثير»)، التأكيد («نحن نعرف أن المقاول هو السبب»)، الإرساء على الرقم الأول («التقدير 480 مليونًا»)، والتفاؤل في الجداول. مهمتك تسميتها بأدب وبالأرقام: «الرقم 480 من دراسة قبل تغيير الطريق؛ التقدير المحدث 310».","خطة 100 يوم تحوّل التوصية إلى تنفيذ: ثلاث موجات (استقرار، بناء الآليات، مراجعة المحفظة)، لكل بند مالك وموعد ومؤشر وعتبة تصعيد. لوحة المتابعة ≤ 8 مؤشرات، ومراجعة أسبوعية للتصعيد. الدفاع أمام اللجنة: توقع الأسئلة الخمسة الأصعب وجهّز لكل منها رقمًا حاسمًا وشرطًا يغيّر رأيك."],"terms":[{"ar":"الافتراض غير المعلن","en":"Unstated Assumption","definition":"افتراض يعتمد عليه التحليل دون التصريح به."},{"ar":"انحياز الإرساء","en":"Anchoring Bias","definition":"التعلق بأول رقم يُطرح."},{"ar":"خطة 100 يوم","en":"100-Day Plan","definition":"خطة تنفيذ بثلاث موجات بمالك ومؤشر لكل بند."},{"ar":"بوابة التحقق","en":"Validation Gate","definition":"نقطة لاحقة يُراجع فيها الافتراض قبل الالتزام النهائي."},{"ar":"الدفاع عن التوصية","en":"Recommendation Defense","definition":"الرد على اعتراضات القيادة بالأرقام مع تسمية ما يغيّر الرأي."}],"method_steps":["اقرأ الحالة مرتين: الأولى للمشكلة، الثانية لصيد الافتراضات والتناقضات.","اكتب قائمة «ما لا أعرفه» وقدّر أثر كل مجهول على القرار.","رتب الأهداف المتعارضة صراحة وفق أولويات صاحب القرار.","حلل الخيارات (بما فيها المقلّص والمؤجل) بالسيناريوهات.","سمّ الانحيازات في البيانات أو في مواقف أصحاب المصلحة بالأرقام.","اكتب التوصية بالهرم مع بوابات تحقق للافتراضات الحاكمة.","ابنِ خطة 100 يوم بثلاث موجات ولوحة ≤ 8 مؤشرات.","جهّز الأسئلة الخمسة الأصعب وأجوبتها الرقمية."]}'::jsonb, 1)
  on conflict (id) do update set title = excluded.title, content = excluded.content, order_index = excluded.order_index;
